	@Override
	protected void startUp()
	{
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "bossingbis");
			t.setDaemon(true);
			// the search is background work; let the game client have the CPU first
			t.setPriority(Thread.MIN_PRIORITY);
			return t;
		});
		panel = new BossingBisPanel(this, itemManager);
		executor.submit(() ->
		{
			try
			{
				GameData data = GameData.load(gson);
				PrepPlanner prep = new PrepPlanner(PrepData.load(gson));
				planner = prep;
				resolver = new MonsterResolver(data);
				gameData = data;
				List<BossingBisPanel.BossChoice> bosses = new ArrayList<>();
				for (Map.Entry<String, PrepData.BossInfo> e : prep.data().bosses().entrySet())
				{
					bosses.add(new BossingBisPanel.BossChoice(e.getKey(), e.getValue().getName(),
						e.getValue().getSlayerTask()));
				}
				String saved = config.selectedBoss();
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.setBosses(bosses, saved);
					}
				});
				// the bank may have been opened while the data was loading
				clientThread.invokeLater(() -> recalculate(Trigger.FORCE));
			}
			catch (Exception e)
			{
				log.warn("Unable to load BossingBIS data", e);
			}
		});

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("BossingBIS")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		updateHighlightColors();
		overlayManager.add(overlay);
		tagManager.registerTag(BANK_TAG, this::inBankTag);
		clientThread.invokeLater(this::loadSavedBank);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(() ->
		{
			if (BANK_TAG.equals(bankTagsService.getActiveTag()))
			{
				bankTagsService.closeBankTag();
			}
		});
		tagManager.unregisterTag(BANK_TAG);
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		cancelRunning();
		executor.shutdownNow();
		executor = null;
		running = null;
		runningCancel = null;
		gameData = null;
		resolver = null;
		planner = null;
		bankItems = null;
		wornItems.clear();
		inventoryItems.clear();
		itemNames.clear();
		lastSignature = Collections.emptyMap();
		lastGearSignature = Collections.emptySet();
		selectedMonsterId = null;
		savedBank = null;
		bankOpen = false;
		lastReady = null;
		outcome = null;
		selectedType = null;
		highlightIds = new int[0];
		supplyHighlightIds = new int[0];
		panel = null;
	}

