	/**
	 * What caused a recalculation, which decides what counts as a change worth a new search.
	 */
	private enum Trigger
	{
		/** Always search again (settings, the panel's button, a new boss or monster pick). */
		FORCE,
		/** The bank changed: search again if anything you own was added or used up. */
		BANK,
		/**
		 * Worn items or inventory changed: only search again if the gear you own changed, so
		 * eating food or drinking potions does not start a new search.
		 */
		GEAR_ONLY
	}

	/**
	 * Snapshots everything needed on the client thread, then runs the search on the worker thread.
	 */
	private void recalculate(Trigger trigger)
	{
		if (executor == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		GameData data = gameData;
		MonsterResolver res = resolver;
		PrepPlanner prep = planner;
		if (bankItems == null || data == null || res == null || prep == null)
		{
			return;
		}

		// Total owned quantity by item, and the preferred source of each: worn first, then
		// inventory, then bank, so the bank is only highlighted for what is not already on you.
		Map<Integer, Integer> totals = new HashMap<>();
		Map<Integer, ItemSource> sources = new LinkedHashMap<>();
		addSource(wornItems, ItemSource.WORN, totals, sources);
		addSource(inventoryItems, ItemSource.INVENTORY, totals, sources);
		addSource(bankItems, ItemSource.BANK, totals, sources);
		addSource(potionStoreItems, ItemSource.BANK, totals, sources);
		if (config.includeGroupStorage())
		{
			addSource(groupStorageItems, ItemSource.GROUP_STORAGE, totals, sources);
		}

		// Moving items between bank and inventory does not change the totals, so the plan stays
		// put while you withdraw.
		Set<Integer> gearSignature = new HashSet<>();
		for (int id : totals.keySet())
		{
			if (data.getItem(id) != null)
			{
				gearSignature.add(id);
			}
		}
		if (trigger == Trigger.BANK && totals.equals(lastSignature))
		{
			return;
		}
		if (trigger == Trigger.GEAR_ONLY && gearSignature.equals(lastGearSignature))
		{
			return;
		}
		lastSignature = totals;
		lastGearSignature = gearSignature;

		String boss = config.selectedBoss();
		if (boss == null || prep.data().boss(boss) == null)
		{
			outcome = null;
			updateHighlights();
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.showMessage("Pick a boss above.");
				}
			});
			return;
		}

		Map<String, Integer> quantitiesByName = new HashMap<>();
		Map<String, Set<Integer>> bankIdsByName = new HashMap<>();
		Map<String, Integer> anyIdByName = new HashMap<>();
		for (Map.Entry<Integer, Integer> e : totals.entrySet())
		{
			String name = itemNames.get(e.getKey());
			if (name != null)
			{
				quantitiesByName.merge(name, e.getValue(), Integer::sum);
				anyIdByName.putIfAbsent(name, e.getKey());
				if (bankItems.containsKey(e.getKey()) || potionStoreItems.containsKey(e.getKey()))
				{
					bankIdsByName.computeIfAbsent(name, n -> new HashSet<>()).add(e.getKey());
				}
			}
		}
		// runes in the rune pouch count as owned, though they aren't items in the bank
		addRunePouch(quantitiesByName, anyIdByName);
		OwnedItems owned = OwnedItems.of(quantitiesByName, bankIdsByName, anyIdByName);
		Map<Integer, String> names = new HashMap<>(itemNames);

		Map<Integer, Optimizer.Candidate> candidates = new LinkedHashMap<>();
		// Uncharged, empty, inactive and broken items cannot be used as they are. Their working
		// versions are kept aside to show what charging or repairing them would give.
		Map<Integer, Optimizer.Candidate> chargeableById = new LinkedHashMap<>();
		for (Map.Entry<Integer, ItemSource> e : sources.entrySet())
		{
			ItemSource source = e.getValue();
			if ((source == ItemSource.WORN && !config.includeEquipped())
				|| (source == ItemSource.INVENTORY && !config.includeInventory()))
			{
				continue;
			}
			GearItem item = data.getItem(e.getKey());
			if (item == null)
			{
				continue;
			}
			if (!item.isUsable())
			{
				GearItem usable = data.findUsableVariant(item);
				if (usable != null)
				{
					chargeableById.putIfAbsent(usable.getId(), new Optimizer.Candidate(usable, e.getKey()));
				}
				continue;
			}
			candidates.putIfAbsent(item.getId(), new Optimizer.Candidate(item, e.getKey()));
		}
		List<Optimizer.Candidate> chargeable = new ArrayList<>();
		for (Optimizer.Candidate c : chargeableById.values())
		{
			// already owned in working form, so charging this copy changes nothing
			if (!candidates.containsKey(c.getItem().getId()))
			{
				chargeable.add(c);
			}
		}

		GearItem[] worn = new GearItem[EquipmentSlot.values().length];
		for (int id : wornItems.keySet())
		{
			GearItem item = data.getItem(id);
			if (item != null && item.isUsable())
			{
				worn[item.getSlot().ordinal()] = item;
			}
		}

		PlayerSetup setup = buildSetup();
		Settings settings = new Settings(boss, selectedMonsterId, config.showPreparation(),
			config.prayerPotions(), config.prayerRestore(), config.combatPotions(), config.fillFood(),
			config.lootTools().getMaxKills(), config.specWeapon(), config.burstTargets(), selectedFood,
			config.serpentineHelm(), config.planSwitches(), config.switchTolerance(), config.wikiSwitches(), selectedAmmo,
			selectedSpell, spellbookName(), client.getRealSkillLevel(Skill.MAGIC), finishedQuests(prep.data().spellQuests()),
			client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) == 1);

		cancelRunning();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.showMessage("Calculating...");
			}
		});

		List<Optimizer.Candidate> candidateList = new ArrayList<>(candidates.values());
		AtomicBoolean cancel = new AtomicBoolean();
		runningCancel = cancel;
		running = executor.submit(() -> runOptimisation(res, prep, cancel, candidateList, chargeable, sources, owned,
			names, worn, setup, settings));
	}

	private static void addSource(Map<Integer, Integer> items, ItemSource source, Map<Integer, Integer> totals,
		Map<Integer, ItemSource> sources)
	{
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			totals.merge(e.getKey(), e.getValue(), Integer::sum);
			sources.putIfAbsent(e.getKey(), source);
		}
	}

	private void cancelRunning()
	{
		if (runningCancel != null)
		{
			runningCancel.set(true);
		}
		if (running != null)
		{
			running.cancel(false);
		}
	}

	/**
	 * Config values snapshotted on the client thread for the worker.
	 */
	@lombok.Value
	private static class Settings
	{
		String boss;
		Integer selectedMonsterId;
		boolean showPreparation;
		int prayerPotions;
		PrayerRestore prayerRestore;
		int combatPotions;
		boolean fillFood;
		int lootMaxKills;
		boolean specWeapon;
		int burstTargets;
		String preferredFood;
		BossingBisConfig.SerpentineHelm serpentineHelm;
		boolean planSwitches;
		int switchTolerance;
		boolean wikiSwitches;
		/** Ammo and spell picked in the panel, so the inventory is planned for the style they make best. */
		Integer selectedAmmo;
		String selectedSpell;
		/** For teleport spells and fairy rings. */
		String spellbook;
		int magicLevel;
		Set<String> finishedQuests;
		boolean fairyRingsWithoutStaff;
	}

	private PlayerSetup buildSetup()
	{
		BossingBisConfig.MeleeBoost melee = config.meleeBoost();
		BossingBisConfig.RangedBoost ranged = config.rangedBoost();
		BossingBisConfig.MagicBoost magic = config.magicBoost();

		boolean ancients;
		switch (config.spellbook())
		{
			case ANCIENT:
				ancients = true;
				break;
			case STANDARD:
				ancients = false;
				break;
			default:
				ancients = client.getVarbitValue(VarbitID.SPELLBOOK) == SPELLBOOK_ANCIENT;
				break;
		}

		return PlayerSetup.builder()
			.attack(boost(client.getRealSkillLevel(Skill.ATTACK), melee.getFlat(), melee.getPercent()))
			.strength(boost(client.getRealSkillLevel(Skill.STRENGTH), melee.getFlat(), melee.getPercent()))
			.ranged(boost(client.getRealSkillLevel(Skill.RANGED), ranged.getFlat(), ranged.getPercent()))
			.magic(boost(client.getRealSkillLevel(Skill.MAGIC), magic.getFlat(), magic.getPercent()))
			.hitpoints(client.getRealSkillLevel(Skill.HITPOINTS))
			.meleeAccuracyPrayer(config.meleePrayer().getAccuracy())
			.meleeStrengthPrayer(config.meleePrayer().getStrength())
			.rangedAccuracyPrayer(config.rangedPrayer().getAccuracy())
			.rangedStrengthPrayer(config.rangedPrayer().getStrength())
			.magicAccuracyPrayer(config.magicPrayer().getAccuracy())
			.magicDamagePrayer(config.magicPrayer().getDamage())
			// off task unless the boss needs a task; see runOptimisation
			.onSlayerTask(false)
			.ancientSpellbook(ancients)
			.kandarinHardDiary(config.kandarinHard())
			.blowpipeDartStrength(config.blowpipeDart().getRangedStrength())
			.build();
	}

	/** Spellbook names by the SPELLBOOK varbit's value. */
	private static final String[] SPELLBOOKS = {"standard", "ancient", "lunar", "arceuus"};
	private static final int[] RUNE_POUCH_TYPES = {VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2,
		VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_TYPE_4};
	private static final int[] RUNE_POUCH_QUANTITIES = {VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4};

	/**
	 * The spellbook the player is on, for teleport spells. Runs on the client thread.
	 */
	private String spellbookName()
	{
		int value = client.getVarbitValue(VarbitID.SPELLBOOK);
		return value >= 0 && value < SPELLBOOKS.length ? SPELLBOOKS[value] : null;
	}

	/**
	 * Which of these quests (RuneLite Quest names) the player has finished. Runs on the client thread.
	 */
	private Set<String> finishedQuests(Set<String> names)
	{
		Set<String> out = new HashSet<>();
		for (Quest quest : Quest.values())
		{
			if (names.contains(quest.name()) && quest.getState(client) == QuestState.FINISHED)
			{
				out.add(quest.name());
			}
		}
		return out;
	}

	/**
	 * Adds the runes in the rune pouch to what the player owns: they aren't items in the bank. Read
	 * the way RuneLite's Rune Pouch plugin reads them. Runs on the client thread.
	 */
	private void addRunePouch(Map<String, Integer> quantitiesByName, Map<String, Integer> anyIdByName)
	{
		EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		for (int i = 0; i < RUNE_POUCH_TYPES.length; i++)
		{
			int type = client.getVarbitValue(RUNE_POUCH_TYPES[i]);
			int quantity = client.getVarbitValue(RUNE_POUCH_QUANTITIES[i]);
			int itemId = type > 0 && quantity > 0 ? runes.getIntValue(type) : -1;
			if (itemId > 0)
			{
				String name = itemNames.computeIfAbsent(itemId, id -> itemManager.getItemComposition(id).getName());
				quantitiesByName.merge(name, quantity, Integer::sum);
				anyIdByName.putIfAbsent(name, itemId);
			}
		}
	}

	private static int boost(int level, int flat, int percent)
	{
		return level + flat + level * percent / 100;
	}

	/**
	 * Runs on the worker thread.
	 */
	private void runOptimisation(MonsterResolver res, PrepPlanner prep, AtomicBoolean cancel,
		List<Optimizer.Candidate> candidates, List<Optimizer.Candidate> chargeable, Map<Integer, ItemSource> sources,
		OwnedItems owned, Map<Integer, String> names, GearItem[] worn, PlayerSetup offTask, Settings settings)
	{
		try
		{
			String boss = settings.getBoss();
			PrepData.BossInfo info = prep.data().boss(boss);
			// bosses that can only be fought on a Slayer task always get the Slayer helmet's bonus
			PlayerSetup setup = offTask.toBuilder().onSlayerTask(info.getSlayerTask() != null).build();
			List<Monster> choices = res.forBoss(info.getMonsters());
			if (choices.isEmpty())
			{
				showMessage("No monster stats found for " + info.getName() + ".");
				return;
			}
			Monster monster = null;
			if (settings.getSelectedMonsterId() != null)
			{
				for (Monster m : choices)
				{
					if (m.getId() == settings.getSelectedMonsterId())
					{
						monster = m;
					}
				}
			}
			// with nothing picked, a boss with several phases or monsters is planned as a whole fight
			boolean wholeFight = monster == null && info.isWholeFight() && choices.size() > 1 && settings.isPlanSwitches();
			if (monster == null)
			{
				monster = choices.get(0);
			}

			// gear the boss requires; only enforce what you own, and flag the rest
			Set<String> ownedGearNames = new HashSet<>();
			for (Optimizer.Candidate c : candidates)
			{
				ownedGearNames.add(c.getItem().getName());
			}
			List<PrepPlan.Requirement> requirements = prep.requirements(boss, owned, ownedGearNames);
			Map<EquipmentSlot, Set<String>> required = new EnumMap<>(EquipmentSlot.class);
			for (PrepPlan.Requirement r : requirements)
			{
				if (r.isOwned())
				{
					required.put(r.getSlot(), new HashSet<>(r.getAccepted()));
				}
			}
			List<PrepPlan.Preference> preferences = prep.preferences(boss);
			int minWeight = prep.minWeight(boss);
			boolean poisons = prep.poisons(boss);

			Optimizer optimizer = new Optimizer(setup, monster, cancel);
			Map<AttackType, StyleResult> results = new EnumMap<>(AttackType.class);
			Map<AttackType, Double> serpentineCost = new EnumMap<>(AttackType.class);
			Map<AttackType, List<String>> keptNotes = new EnumMap<>(AttackType.class);
			Map<AttackType, Double> keptCost = new EnumMap<>(AttackType.class);
			Set<AttackType> tooLight = EnumSet.noneOf(AttackType.class);
			for (AttackType type : AttackType.values())
			{
				if (type != AttackType.BURST)
				{
					StyleResult r = optimizer.optimise(candidates, type, required, minWeight);
					if (minWeight > 0 && !r.isValid())
					{
						// nothing owned is heavy enough: show the best set anyway, with a warning
						r = optimizer.optimise(candidates, type, required);
						if (r.isValid())
						{
							tooLight.add(type);
						}
					}
					int weight = tooLight.contains(type) ? 0 : minWeight;
					r = applyPreferences(optimizer, candidates, type, r, required, preferences, weight, keptNotes, keptCost);
					results.put(type, poisons ? preferSerpentine(optimizer, candidates, type, r, required,
						settings.getSerpentineHelm().getPercent(), serpentineCost, weight) : r);
				}
			}
			Map<AttackType, List<StyleResult.Alternative>> spellOptions = new EnumMap<>(AttackType.class);
			spellOptions.put(AttackType.MAGIC, optimizer.spellOptions(results.get(AttackType.MAGIC)));
			if (settings.getBurstTargets() > 0 && prep.stacks(boss))
			{
				// casting Ancients by hand on a stack: magic on the Ancient spellbook, DPS times the targets
				PlayerSetup burstSetup = setup.toBuilder().ancientSpellbook(true)
					.burstTargets(settings.getBurstTargets()).build();
				Optimizer burstOptimizer = new Optimizer(burstSetup, monster, cancel);
				StyleResult r = burstOptimizer.optimise(candidates, AttackType.MAGIC, required);
				spellOptions.put(AttackType.BURST, burstOptimizer.spellOptions(r));
				results.put(AttackType.BURST, new StyleResult(AttackType.BURST, r.getResult(), r.getGear(),
					r.getCombinationsTried(), r.getItemsConsidered(), r.getItemsAfterPruning(), r.getSetsConsidered(),
					r.isStoppedEarly(), r.getAlternatives()));
			}

			Map<AttackType, Double> givenUp = new EnumMap<>(AttackType.class);
			for (AttackType t : AttackType.values())
			{
				double cost = serpentineCost.getOrDefault(t, 0.0) + keptCost.getOrDefault(t, 0.0);
				if (cost > 0)
				{
					givenUp.put(t, cost);
				}
			}
			Map<AttackType, OptimizationOutcome.ChargeHint> hints = chargeHints(optimizer, candidates, chargeable,
				results, required, givenUp);

			OptimizationOutcome.CurrentGear current = currentGear(setup, monster, worn);

			// the best style with the ammo and spell picked in the panel: the inventory is planned for it
			List<StyleResult.Alternative> ammoOptions = optimizer.ammoOptions(results.get(AttackType.RANGED), candidates);
			StyleResult best = OptimizationOutcome.best(results, settings.getSelectedAmmo(), settings.getSelectedSpell(),
				ammoOptions, spellOptions);
			List<OptimizationOutcome.Phase> phases = new ArrayList<>();
			List<PrepPlan.Switch> switches = new ArrayList<>();
			Set<String> plannedWeapons = new HashSet<>();
			String mainWeapon = bestWeaponName(best);
			if (mainWeapon != null)
			{
				plannedWeapons.add(mainWeapon);
			}
			if (wholeFight && best != null)
			{
				planPhases(choices, monster, best, setup, cancel, candidates, required, preferences, minWeight,
					settings.getSwitchTolerance(), names, phases, switches, plannedWeapons);
			}

			PrepPlan plan = settings.isShowPreparation()
				? prep.plan(PrepPlanner.Request.builder()
				.boss(boss)
				.bestType(best == null ? null : best.getType())
				.requirements(requirements)
				.owned(owned)
				.switches(switches)
				.wikiSwitches(settings.isWikiSwitches())
				.prayerPotions(settings.getPrayerPotions())
				.prayerRestore(settings.getPrayerRestore())
				.combatPotions(settings.getCombatPotions())
				.fillFood(settings.isFillFood())
				.monsterName(monster.getName())
				.monsterVersion(monster.getVersion())
				.lootMaxKills(settings.getLootMaxKills())
				.monsterHitpoints(monster.getHitpoints())
				.plannedWeapons(plannedWeapons)
				.wornNames(wornNames(best))
				.suggestSpecWeapon(settings.isSpecWeapon())
				.preferredFood(settings.getPreferredFood())
				.spellbook(settings.getSpellbook())
				.magicLevel(settings.getMagicLevel())
				.finishedQuests(settings.getFinishedQuests())
				.fairyRingsWithoutStaff(settings.isFairyRingsWithoutStaff())
				.venomImmune(best != null && best.getGear()[EquipmentSlot.HEAD.ordinal()] != null
					&& isChargedSerpentine(best.getGear()[EquipmentSlot.HEAD.ordinal()].getItem()))
				.build())
				: new PrepPlan(requirements, List.of(), List.of(), List.of(), List.of(), 0, Set.of(), List.of());

			OptimizationOutcome done = new OptimizationOutcome(boss, info.getName(), info.getSlayerTask(), monster,
				wholeFight, info.isWholeFight() && choices.size() > 1, choices, results, sources, setup,
				candidates.size(), hints, current, plan, settings.getBurstTargets(), keptNotes,
				ammoOptions, minWeight, tooLight, serpentineCost,
				spellOptions, phases, best == null ? null : best.getType());
			outcome = done;
			updateHighlights();
			clientThread.invokeLater(() ->
			{
				lastReady = null;
				updateReadiness();
			});
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.showOutcome(done, selectedType);
				}
			});
		}
		catch (CancellationException e)
		{
			log.debug("BossingBIS search cancelled");
		}
		catch (Exception e)
		{
			log.warn("BossingBIS search failed", e);
			showMessage("Something went wrong while calculating. See the client log for details.");
		}
	}

	private void showMessage(String message)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.showMessage(message);
			}
		});
	}

	/**
	 * For a whole-fight plan: the best set against each of the fight's other monsters or phases,
	 * and the items it adds to the main set, which become switches to carry. Worked out before the
	 * trip from the monsters' stats only.
	 *
	 * @param switchTolerance how much DPS (percent) a phase may give up to carry fewer switches
	 */
	static void planPhases(List<Monster> choices, Monster main, StyleResult mainBest, PlayerSetup setup,
		AtomicBoolean cancel, List<Optimizer.Candidate> candidates, Map<EquipmentSlot, Set<String>> required,
		List<PrepPlan.Preference> preferences, int minWeight, int switchTolerance, Map<Integer, String> names,
		List<OptimizationOutcome.Phase> phases, List<PrepPlan.Switch> switches, Set<String> plannedWeapons)
	{
		phases.add(new OptimizationOutcome.Phase(main, mainBest.getType(), mainBest.getResult().getDps(), List.of(),
			0, 0));
		Set<Integer> switchIds = new HashSet<>();
		for (Monster m : choices)
		{
			if (m == main)
			{
				continue;
			}
			Optimizer optimizer = new Optimizer(setup, m, cancel);
			StyleResult best = null;
			for (AttackType type : AttackType.values())
			{
				if (type == AttackType.BURST)
				{
					continue;
				}
				StyleResult r = optimizer.optimise(candidates, type, required, minWeight);
				if (!r.isValid())
				{
					r = optimizer.optimise(candidates, type, required);
				}
				r = applyPreferences(optimizer, candidates, type, r, required, preferences, 0,
					new EnumMap<>(AttackType.class), new EnumMap<>(AttackType.class));
				if (r.isValid() && (best == null || r.getResult().getDps() > best.getResult().getDps()))
				{
					best = r;
				}
			}
			if (best == null)
			{
				continue;
			}
			int fullSwitches = switchesFrom(best, mainBest).size();
			double fullDps = best.getResult().getDps();
			// carry fewer switches where keeping the main set's items costs little DPS
			best = fewerSwitches(optimizer, candidates, best, mainBest, required, minWeight, switchTolerance);
			List<Optimizer.Candidate> extra = switchesFrom(best, mainBest);
			for (Optimizer.Candidate c : extra)
			{
				String name = names.get(c.getOwnedItemId());
				if (switchIds.add(c.getOwnedItemId()) && name != null)
				{
					switches.add(new PrepPlan.Switch(name, "switch for " + m.displayName()));
				}
				if (c.getItem().getSlot() == EquipmentSlot.WEAPON)
				{
					plannedWeapons.add(c.getItem().getName());
				}
			}
			phases.add(new OptimizationOutcome.Phase(m, best.getType(), best.getResult().getDps(), extra,
				fullSwitches - extra.size(), fullDps - best.getResult().getDps()));
		}
	}

	/**
	 * The items of a set that differ from the main set, which would have to be carried.
	 */
	private static List<Optimizer.Candidate> switchesFrom(StyleResult set, StyleResult mainBest)
	{
		List<Optimizer.Candidate> extra = new ArrayList<>();
		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			Optimizer.Candidate c = set.getGear()[slot.ordinal()];
			Optimizer.Candidate mainItem = mainBest.getGear()[slot.ordinal()];
			if (c != null && (mainItem == null || mainItem.getItem().getId() != c.getItem().getId()))
			{
				extra.add(c);
			}
		}
		return extra;
	}

	/**
	 * Trims a monster's best set down to fewer switches, giving up no more than {@code percent} of
	 * its DPS. First tries the main set as it is (no switches at all), then keeps the main set's
	 * item slot by slot, cheapest first, while the set stays within the allowance.
	 */
	private static StyleResult fewerSwitches(Optimizer optimizer, List<Optimizer.Candidate> candidates,
		StyleResult best, StyleResult mainBest, Map<EquipmentSlot, Set<String>> required, int minWeight, int percent)
	{
		if (percent <= 0)
		{
			return best;
		}
		double floor = best.getResult().getDps() * 100 / (100 + percent);

		Map<EquipmentSlot, Set<String>> all = keepSlots(required, mainBest, EnumSet.allOf(EquipmentSlot.class));
		StyleResult asIs = optimizer.optimise(candidates, mainBest.getType(), all, minWeight);
		if (asIs.isValid() && asIs.getResult().getDps() >= floor)
		{
			return asIs;
		}

		// slots whose switch could be dropped, cheapest first
		List<EquipmentSlot> slots = new ArrayList<>();
		Map<EquipmentSlot, Double> dpsKept = new EnumMap<>(EquipmentSlot.class);
		for (Optimizer.Candidate c : switchesFrom(best, mainBest))
		{
			EquipmentSlot slot = c.getItem().getSlot();
			if (mainBest.getGear()[slot.ordinal()] == null || required.containsKey(slot))
			{
				continue;
			}
			StyleResult r = optimizer.optimise(candidates, best.getType(), keepSlots(required, mainBest, EnumSet.of(slot)),
				minWeight);
			if (r.isValid() && r.getResult().getDps() >= floor)
			{
				slots.add(slot);
				dpsKept.put(slot, r.getResult().getDps());
			}
		}
		slots.sort((a, b) -> Double.compare(dpsKept.get(b), dpsKept.get(a)));

		StyleResult current = best;
		EnumSet<EquipmentSlot> kept = EnumSet.noneOf(EquipmentSlot.class);
		for (EquipmentSlot slot : slots)
		{
			EnumSet<EquipmentSlot> trying = EnumSet.copyOf(kept);
			trying.add(slot);
			StyleResult r = optimizer.optimise(candidates, best.getType(), keepSlots(required, mainBest, trying), minWeight);
			if (r.isValid() && r.getResult().getDps() >= floor
				&& switchesFrom(r, mainBest).size() < switchesFrom(current, mainBest).size())
			{
				kept = trying;
				current = r;
			}
		}
		return current;
	}

	/**
	 * The boss's required gear plus the main set's item in each of these slots.
	 */
	private static Map<EquipmentSlot, Set<String>> keepSlots(Map<EquipmentSlot, Set<String>> required,
		StyleResult mainBest, Set<EquipmentSlot> slots)
	{
		Map<EquipmentSlot, Set<String>> keep = new EnumMap<>(EquipmentSlot.class);
		keep.putAll(required);
		for (EquipmentSlot slot : slots)
		{
			Optimizer.Candidate c = mainBest.getGear()[slot.ordinal()];
			if (c != null && !keep.containsKey(slot))
			{
				keep.put(slot, Set.of(c.getItem().getName()));
			}
		}
		return keep;
	}

	private static String bestWeaponName(StyleResult best)
	{
		if (best == null || best.getGear() == null)
		{
			return null;
		}
		Optimizer.Candidate weapon = best.getGear()[EquipmentSlot.WEAPON.ordinal()];
		return weapon == null ? null : weapon.getItem().getName();
	}

	/**
	 * Applies the boss's recommended items in order: for each, searches again with one of its items
	 * kept and uses that set when the best set without it is no more than its percentage better.
	 * Records what was kept and the DPS given up.
	 */
	static StyleResult applyPreferences(Optimizer optimizer, List<Optimizer.Candidate> candidates,
		AttackType type, StyleResult best, Map<EquipmentSlot, Set<String>> required, List<PrepPlan.Preference> preferences,
		int minWeight, Map<AttackType, List<String>> notes, Map<AttackType, Double> cost)
	{
		StyleResult result = best;
		Map<EquipmentSlot, Set<String>> kept = new EnumMap<>(EquipmentSlot.class);
		kept.putAll(required);
		for (PrepPlan.Preference p : preferences)
		{
			if (!result.isValid() || kept.containsKey(p.getSlot()))
			{
				continue;
			}
			Optimizer.Candidate current = result.getGear()[p.getSlot().ordinal()];
			if (current != null && p.getItems().contains(current.getItem().getName()))
			{
				kept.put(p.getSlot(), Set.of(current.getItem().getName()));
				continue;
			}
			Set<String> owned = new HashSet<>();
			for (Optimizer.Candidate c : candidates)
			{
				if (p.getItems().contains(c.getItem().getName()))
				{
					owned.add(c.getItem().getName());
				}
			}
			if (owned.isEmpty())
			{
				continue;
			}
			Map<EquipmentSlot, Set<String>> with = new EnumMap<>(EquipmentSlot.class);
			with.putAll(kept);
			with.put(p.getSlot(), owned);
			StyleResult r = optimizer.optimise(candidates, type, with, minWeight);
			double dps = result.getResult().getDps();
			if (!r.isValid() || r.getResult().getDps() * (100 + p.getWithinPercent()) < dps * 100)
			{
				continue;
			}
			double lost = dps - r.getResult().getDps();
			cost.merge(type, lost, Double::sum);
			String item = r.getGear()[p.getSlot().ordinal()].getItem().getName();
			notes.computeIfAbsent(type, t -> new ArrayList<>()).add(item + " kept on (" + p.getReason() + ")"
				+ (lost > 0.005 ? ": " + String.format("%.2f", lost) + " DPS less." : ": no DPS lost."));
			kept.put(p.getSlot(), owned);
			result = r;
		}
		return result;
	}

	/**
	 * On bosses that poison or envenom, searches again with a charged Serpentine helm (or Tanzanite
	 * or Magma helm) and uses that set when the setting allows the DPS it costs. Returns the original
	 * result when it doesn't apply.
	 */
	private static StyleResult preferSerpentine(Optimizer optimizer, List<Optimizer.Candidate> candidates,
		AttackType type, StyleResult best, Map<EquipmentSlot, Set<String>> required, int percent,
		Map<AttackType, Double> cost, int minWeight)
	{
		if (percent <= 0 || !best.isValid() || required.containsKey(EquipmentSlot.HEAD))
		{
			return best;
		}
		Optimizer.Candidate head = best.getGear()[EquipmentSlot.HEAD.ordinal()];
		if (head != null && isChargedSerpentine(head.getItem()))
		{
			return best;
		}
		Set<String> owned = new HashSet<>();
		List<Optimizer.Candidate> usable = new ArrayList<>();
		for (Optimizer.Candidate c : candidates)
		{
			if (SERPENTINE_HELMS.contains(c.getItem().getName()) && !isChargedSerpentine(c.getItem()))
			{
				continue; // uncharged: no protection
			}
			usable.add(c);
			if (isChargedSerpentine(c.getItem()))
			{
				owned.add(c.getItem().getName());
			}
		}
		if (owned.isEmpty())
		{
			return best;
		}
		Map<EquipmentSlot, Set<String>> withHelm = new EnumMap<>(EquipmentSlot.class);
		withHelm.putAll(required);
		withHelm.put(EquipmentSlot.HEAD, owned);
		StyleResult kept = optimizer.optimise(usable, type, withHelm, minWeight);
		double bestDps = best.getResult().getDps();
		if (!kept.isValid() || (percent != Integer.MAX_VALUE
			&& kept.getResult().getDps() * (100 + percent) < bestDps * 100))
		{
			return best;
		}
		cost.put(type, bestDps - kept.getResult().getDps());
		return kept;
	}

	private static Set<String> wornNames(StyleResult best)
	{
		Set<String> names = new HashSet<>();
		if (best != null && best.isValid())
		{
			for (Optimizer.Candidate c : best.getGear())
			{
				if (c != null)
				{
					names.add(c.getItem().getName());
				}
			}
		}
		return names;
	}

	private static boolean isChargedSerpentine(GearItem item)
	{
		return SERPENTINE_HELMS.contains(item.getName()) && !"Uncharged".equals(item.getVersion());
	}

	/**
	 * A second search as if the uncharged items were charged; reported only where it would win.
	 */
	private static Map<AttackType, OptimizationOutcome.ChargeHint> chargeHints(Optimizer optimizer,
		List<Optimizer.Candidate> candidates, List<Optimizer.Candidate> chargeable, Map<AttackType, StyleResult> results,
		Map<EquipmentSlot, Set<String>> required, Map<AttackType, Double> givenUp)
	{
		Map<AttackType, OptimizationOutcome.ChargeHint> hints = new EnumMap<>(AttackType.class);
		if (chargeable.isEmpty())
		{
			return hints;
		}
		Set<Optimizer.Candidate> extra = new HashSet<>(chargeable);
		List<Optimizer.Candidate> withCharged = new ArrayList<>(candidates);
		withCharged.addAll(chargeable);
		for (AttackType type : AttackType.values())
		{
			if (type == AttackType.BURST)
			{
				continue;
			}
			StyleResult charged = optimizer.optimise(withCharged, type, required);
			// compare with the best set before any recommended items or Serpentine helm
			double withoutCharging = results.get(type).getResult().getDps() + givenUp.getOrDefault(type, 0.0);
			if (!charged.isValid() || charged.getResult().getDps() <= withoutCharging)
			{
				continue;
			}
			List<String> needed = new ArrayList<>();
			for (Optimizer.Candidate c : charged.getGear())
			{
				if (c != null && extra.contains(c))
				{
					needed.add(c.getItem().getName());
				}
			}
			if (!needed.isEmpty())
			{
				hints.put(type, new OptimizationOutcome.ChargeHint(charged.getResult().getDps(), needed));
			}
		}
		return hints;
	}

	private static OptimizationOutcome.CurrentGear currentGear(PlayerSetup setup, Monster monster, GearItem[] worn)
	{
		DpsCalculator calculator = new DpsCalculator(setup, monster);
		OptimizationOutcome.CurrentGear best = null;
		for (AttackType type : AttackType.values())
		{
			CalcResult r = calculator.best(worn, type);
			if (r.getDps() > 0 && (best == null || r.getDps() > best.getResult().getDps()))
			{
				best = new OptimizationOutcome.CurrentGear(type, r);
			}
		}
		return best;
	}

	private void updateHighlights()
	{
		OptimizationOutcome o = outcome;
		if (o == null)
		{
			highlightIds = new int[0];
			supplyHighlightIds = new int[0];
			return;
		}
		supplyHighlightIds = sorted(o.getPrep().getSupplyBankIds());
		StyleResult r = o.resultFor(selectedType, selectedAmmo, selectedSpell);
		if (r == null || !r.isValid())
		{
			highlightIds = new int[0];
			return;
		}
		Set<Integer> ids = new HashSet<>();
		for (Optimizer.Candidate c : r.getGear())
		{
			if (c != null && o.getSources().get(c.getOwnedItemId()) == ItemSource.BANK)
			{
				ids.add(c.getOwnedItemId());
				addVariations(c.getOwnedItemId(), ids);
			}
		}
		highlightIds = sorted(ids);
	}

	/**
	 * Other versions of the same item (Blood Moon armour has new, used and broken ones, each its own
	 * item id), so the bank outline and Show in bank still find it if the id in the bank differs.
	 * Broken and other unusable versions are left out.
	 */
	private void addVariations(int itemId, Set<Integer> ids)
	{
		GameData data = gameData;
		for (int variation : ItemVariationMapping.getVariations(ItemVariationMapping.map(itemId)))
		{
			GearItem item = data == null ? null : data.getItem(variation);
			if (item == null || item.isUsable())
			{
				ids.add(variation);
			}
		}
	}

	private static int[] sorted(Collection<Integer> ids)
	{
		int[] out = new int[ids.size()];
		int n = 0;
		for (int id : ids)
		{
			out[n++] = id;
		}
		Arrays.sort(out);
		return out;
	}
}

package com.bossingbis;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
enum ItemSource
{
	WORN("worn"),
	INVENTORY("inventory"),
	BANK("bank"),
	GROUP_STORAGE("group storage");

	private final String label;
}

package com.bossingbis;

import com.bossingbis.calc.CalcResult;
import com.bossingbis.calc.Optimizer;
import com.bossingbis.calc.PlayerSetup;
import com.bossingbis.calc.StyleResult;
import com.bossingbis.data.AttackType;
import com.bossingbis.data.EquipmentSlot;
import com.bossingbis.data.Monster;
import com.bossingbis.prep.PrepPlan;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * Everything the panel and overlay need from one finished calculation. Immutable once built.
 */
@Value
class OptimizationOutcome
{
	String bossKey;
	String bossName;
	/** The Slayer task the boss can only be fought on, or null. */
	String slayerTask;
	/** The monster the main set is worked out against. */
	Monster monster;
	/** Planned as a whole fight: the main set plus switches for the other monsters or phases. */
	boolean wholeFight;
	/** The boss has several monsters or phases fought together, so a whole-fight plan is offered. */
	boolean wholeFightOffered;
	/** The boss's monsters, for the panel's picker. */
	List<Monster> monsterChoices;
	Map<AttackType, StyleResult> results;
	Map<Integer, ItemSource> sources;
	PlayerSetup setup;
	int itemsScanned;
	/** Per style, what charging or repairing owned items would add; only present when it beats the real result. */
	Map<AttackType, ChargeHint> chargeHints;
	/** DPS of the gear currently worn, in its best style; null if nothing worn can attack. */
	CurrentGear currentGear;
	/** Requirements, inventory and teleports; only the requirements when preparation is turned off. */
	PrepPlan prep;
	/** Monsters each burst or barrage is assumed to hit, for the Burst result. */
	int burstTargets;
	/** Per style, the boss's recommended items that were kept on, and what they cost. */
	Map<AttackType, List<String>> keptNotes;
	/** The ranged set with each owned ammo swapped in, best first; empty when it takes none. */
	List<StyleResult.Alternative> ammoOptions;
	/** The least the worn set must weigh for this boss, in grams; 0 for no limit. */
	int minWeight;
	/** Styles where nothing owned is heavy enough, so the best set shown is too light. */
	Set<AttackType> tooLight;
	/** Per style, the DPS given up to wear a Serpentine helm against poison; only where it was worn. */
	Map<AttackType, Double> serpentineCost;
	/** Magic and Burst: the set with each spell it can cast, best first. */
	Map<AttackType, List<StyleResult.Alternative>> spellOptions;
	/** Whole fight only: the main monster first, then each other monster with its switches. */
	List<Phase> phases;

	/**
	 * The style the inventory was planned for: the best with the ammo and spell picked at the
	 * time. A pick that changes the best style plans again.
	 */
	AttackType plannedType;

	@Value
	static class ChargeHint
	{
		double dps;
		/** Names of the owned items that would need charging or repairing. */
		List<String> items;
	}

	@Value
	static class CurrentGear
	{
		AttackType type;
		CalcResult result;
	}

	/**
	 * One monster or phase of the fight, with the style and DPS of its best set and the items that
	 * set adds to the main one.
	 */
	@Value
	static class Phase
	{
		Monster monster;
		AttackType type;
		double dps;
		List<Optimizer.Candidate> switches;
		/** Switches left out because keeping the main set's items cost little DPS. */
		int switchesSaved;
		/** DPS given up against this monster to carry fewer switches. */
		double dpsGivenUp;
	}

	StyleResult best()
	{
		StyleResult best = null;
		for (StyleResult r : results.values())
		{
			if (r.isValid() && (best == null || r.getResult().getDps() > best.getResult().getDps()))
			{
				best = r;
			}
		}
		return best;
	}

	/**
	 * The result for a type with the ammo and spell picked in the panel.
	 */
	StyleResult adjusted(AttackType type, Integer ammoId, String spell)
	{
		return withSpell(withAmmo(results.get(type), ammoId), spell);
	}

	/**
	 * The best style once the ammo and spell picked in the panel are swapped in, which can make
	 * another style the best.
	 */
	StyleResult best(Integer ammoId, String spell)
	{
		return best(results, ammoId, spell, ammoOptions, spellOptions);
	}

	/**
	 * The best style with the ammo and spell picked in the panel, before an outcome exists.
	 */
	static StyleResult best(Map<AttackType, StyleResult> results, Integer ammoId, String spell,
		List<StyleResult.Alternative> ammoOptions, Map<AttackType, List<StyleResult.Alternative>> spellOptions)
	{
		StyleResult best = null;
		for (StyleResult result : results.values())
		{
			StyleResult r = withSpell(withAmmo(result, ammoId, ammoOptions), spell, spellOptions);
			if (r.isValid() && (best == null || r.getResult().getDps() > best.getResult().getDps()))
			{
				best = r;
			}
		}
		return best;
	}

	/**
	 * The result for a type with the panel's picks, or the best when type is null.
	 */
	StyleResult resultFor(AttackType type, Integer ammoId, String spell)
	{
		return type == null ? best(ammoId, spell) : adjusted(type, ammoId, spell);
	}

	/**
	 * The result for a type, or the overall best when type is null.
	 */
	StyleResult resultFor(AttackType type)
	{
		return type == null ? best() : results.get(type);
	}

	/**
	 * A magic or burst result with the chosen spell, or the result itself when no spell is chosen
	 * or it isn't one of the options for that style.
	 */
	StyleResult withSpell(StyleResult r, String spell)
	{
		return withSpell(r, spell, spellOptions);
	}

	static StyleResult withSpell(StyleResult r, String spell, Map<AttackType, List<StyleResult.Alternative>> spellOptions)
	{
		if (r == null || spell == null)
		{
			return r;
		}
		for (StyleResult.Alternative alt : spellOptions.getOrDefault(r.getType(), List.of()))
		{
			if (spell.equals(alt.getResult().getSpell().getName()))
			{
				return new StyleResult(r.getType(), alt.getResult(), r.getGear(), r.getCombinationsTried(),
					r.getItemsConsidered(), r.getItemsAfterPruning(), r.getSetsConsidered(), r.isStoppedEarly(),
					r.getAlternatives());
			}
		}
		return r;
	}

	/**
	 * The ranged result with the chosen ammo swapped in, or the result itself when no ammo is
	 * chosen or it isn't one of the options.
	 */
	StyleResult withAmmo(StyleResult r, Integer ammoId)
	{
		return withAmmo(r, ammoId, ammoOptions);
	}

	static StyleResult withAmmo(StyleResult r, Integer ammoId, List<StyleResult.Alternative> ammoOptions)
	{
		if (r == null || ammoId == null || r.getType() != AttackType.RANGED)
		{
			return r;
		}
		for (StyleResult.Alternative alt : ammoOptions)
		{
			Optimizer.Candidate ammo = alt.getGear()[EquipmentSlot.AMMO.ordinal()];
			if (ammo != null && ammo.getOwnedItemId() == ammoId)
			{
				return new StyleResult(r.getType(), alt.getResult(), alt.getGear(), r.getCombinationsTried(),
					r.getItemsConsidered(), r.getItemsAfterPruning(), r.getSetsConsidered(), r.isStoppedEarly(),
					r.getAlternatives());
			}
		}
		return r;
	}
}

