package com.bossingbis.calc;

import com.bossingbis.data.AttackType;
import java.util.List;
import lombok.Value;

/**
 * The best loadout found for one attack type.
 */
@Value
public class StyleResult
{
	AttackType type;
	CalcResult result;
	/** Indexed by EquipmentSlot ordinal; null entries are empty slots. Null if nothing could attack. */
	Optimizer.Candidate[] gear;
	long combinationsTried;
	int itemsConsidered;
	int itemsAfterPruning;
	List<String> setsConsidered;
	boolean stoppedEarly;
	/** The best set for each other weapon, best first. */
	List<Alternative> alternatives;

	@Value
	public static class Alternative
	{
		CalcResult result;
		Optimizer.Candidate[] gear;
	}

	public boolean isValid()
	{
		return gear != null && result.getDps() > 0;
	}
}

package com.bossingbis.calc;

import com.bossingbis.data.AttackType;
import com.bossingbis.data.GearItem;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Weapon category behaviour (attack styles, ranged damage type) and ranged ammo compatibility,
 * following the OSRS Wiki DPS calculator.
 */
public final class WeaponRules
{
	private WeaponRules()
	{
	}

	public static final int DEFAULT_ATTACK_SPEED = 4;

	public enum RangedType
	{
		LIGHT, STANDARD, HEAVY
	}

	public enum AmmoKind
	{
		NONE, ARROW, BOLT, JAVELIN, BOLT_RACK, ATLATL_DART, UNSUPPORTED
	}

	/**
	 * The non-defensive stances a weapon category offers for an attack type. Defensive and
	 * longrange stances are never better for damage, so they are left out.
	 */
	public static List<Stance> stances(String category, AttackType type)
	{
		List<Stance> out = new ArrayList<>(3);
		if (type == AttackType.BURST)
		{
			// worked out as MAGIC with a burst setup, never as its own type
			return out;
		}
		switch (category)
		{
			case "2h Sword":
			case "Axe":
				if (type == AttackType.SLASH)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				else if (type == AttackType.CRUSH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				break;
			case "Banner":
				if (type == AttackType.STAB)
				{
					add(out, Stance.ACCURATE);
				}
				else if (type == AttackType.SLASH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				else if (type == AttackType.CRUSH)
				{
					add(out, Stance.CONTROLLED);
				}
				break;
			case "Bladed Staff":
				if (type == AttackType.STAB)
				{
					add(out, Stance.ACCURATE);
				}
				else if (type == AttackType.SLASH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				else if (type == AttackType.MAGIC)
				{
					add(out, Stance.AUTOCAST);
				}
				break;
			case "Bow":
			case "Crossbow":
			case "Thrown":
			case "Chinchompas":
				if (type == AttackType.RANGED)
				{
					add(out, Stance.ACCURATE, Stance.RAPID);
				}
				break;
			case "Bulwark":
				if (type == AttackType.CRUSH)
				{
					add(out, Stance.ACCURATE);
				}
				break;
			case "Multi-Melee":
				if (type == AttackType.STAB)
				{
					add(out, Stance.ACCURATE);
				}
				else if (type == AttackType.SLASH || type == AttackType.CRUSH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				break;
			case "Partisan":
			case "Pickaxe":
				if (type == AttackType.STAB)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				else if (type == AttackType.CRUSH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				break;
			case "Polearm":
				if (type == AttackType.STAB)
				{
					add(out, Stance.CONTROLLED);
				}
				else if (type == AttackType.SLASH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				break;
			case "Powered Staff":
			case "Powered Wand":
				if (type == AttackType.MAGIC)
				{
					add(out, Stance.ACCURATE);
				}
				break;
			case "Claw":
			case "Slash Sword":
				if (type == AttackType.SLASH)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				else if (type == AttackType.STAB)
				{
					add(out, Stance.CONTROLLED);
				}
				break;
			case "Bludgeon":
				if (type == AttackType.CRUSH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				break;
			case "Blunt":
			case "Polestaff":
				if (type == AttackType.CRUSH)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				break;
			case "Spiked":
				if (type == AttackType.CRUSH)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				else if (type == AttackType.STAB)
				{
					add(out, Stance.CONTROLLED);
				}
				break;
			case "Staff":
				if (type == AttackType.CRUSH)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				else if (type == AttackType.MAGIC)
				{
					add(out, Stance.AUTOCAST);
				}
				break;
			case "Scythe":
				if (type == AttackType.SLASH)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				else if (type == AttackType.CRUSH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				break;
			case "Spear":
				if (type.isMelee())
				{
					add(out, Stance.CONTROLLED);
				}
				break;
			case "Stab Sword":
				if (type == AttackType.STAB)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				else if (type == AttackType.SLASH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				break;
			case "Whip":
				if (type == AttackType.SLASH)
				{
					add(out, Stance.ACCURATE, Stance.CONTROLLED);
				}
				break;
			case "Flail":
				if (type == AttackType.SLASH)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				break;
			case "Gun":
				if (type == AttackType.CRUSH)
				{
					add(out, Stance.AGGRESSIVE);
				}
				break;
			case "":
			case "Unarmed":
				if (type == AttackType.CRUSH)
				{
					add(out, Stance.ACCURATE, Stance.AGGRESSIVE);
				}
				break;
			default:
				break;
		}
		return out.isEmpty() ? Collections.emptyList() : out;
	}

	private static void add(List<Stance> out, Stance... stances)
	{
		Collections.addAll(out, stances);
	}

	public static RangedType rangedType(String category)
	{
		switch (category)
		{
			case "Thrown":
				return RangedType.LIGHT;
			case "Crossbow":
			case "Chinchompas":
				return RangedType.HEAVY;
			default:
				return RangedType.STANDARD;
		}
	}

	/**
	 * Powered staves and wands with a built-in spell whose max hit the calculator knows.
	 */
	public static boolean isSupportedPoweredStaff(String name)
	{
		return poweredBaseMaxHit(name, 99) > 0;
	}

	/**
	 * Base max hit of a powered staff's built-in spell, or 0 if unsupported.
	 */
	public static int poweredBaseMaxHit(String name, int magicLevel)
	{
		switch (name)
		{
			case "Starter staff":
				return 8;
			case "Trident of the seas":
			case "Trident of the Seas":
			case "Trident of the Seas (e)":
				return Math.max(1, magicLevel / 3 - 5);
			case "Thammaron's sceptre":
				return Math.max(1, magicLevel / 3 - 8);
			case "Accursed sceptre":
				return Math.max(1, magicLevel / 3 - 6);
			case "Trident of the swamp":
			case "Trident of the Swamp":
			case "Trident of the Swamp (e)":
			case "Dawnbringer":
				return Math.max(1, magicLevel / 3 - 2);
			case "Sanguinesti staff":
			case "Holy sanguinesti staff":
				return Math.max(1, magicLevel / 3);
			case "Tumeken's shadow":
				return Math.max(1, magicLevel / 3 + 1);
			case "Eye of Ayak":
				return Math.max(1, magicLevel / 3 - 6);
			case "Warped sceptre":
				return Math.max(1, (8 * magicLevel + 96) / 37);
			case "Crystal staff (basic)":
			case "Corrupted staff (basic)":
				return 23;
			case "Crystal staff (attuned)":
			case "Corrupted staff (attuned)":
				return 31;
			case "Crystal staff (perfected)":
			case "Corrupted staff (perfected)":
				return 39;
			default:
				return 0;
		}
	}

	private static final Set<String> ANCIENT_AUTOCAST = Collections.unmodifiableSet(new java.util.HashSet<>(java.util.Arrays.asList(
		"Ancient staff", "Master wand", "Kodai wand", "Nightmare staff", "Harmonised Nightmare staff",
		"Eldritch Nightmare staff", "Volatile Nightmare staff", "Staff of the Dead", "Toxic staff of the dead",
		"Staff of Light", "Staff of Balance", "Zuriel's staff (bh)", "Ahrim's staff", "Void knight mace",
		"Accursed sceptre (a)", "Thammaron's sceptre (a)", "Purging staff"
	)));

	public static boolean canAutocastAncients(String name)
	{
		String lower = name.toLowerCase(Locale.ROOT);
		return ANCIENT_AUTOCAST.contains(name) || lower.contains("ancient sceptre") || lower.contains("kodai");
	}

	public static boolean isBlowpipe(String name)
	{
		return name.endsWith("blowpipe");
	}

	/**
	 * Which kind of ammo a ranged weapon fires from the ammo slot.
	 */
	public static AmmoKind ammoKind(GearItem weapon)
	{
		String n = weapon.getName();
		String lower = n.toLowerCase(Locale.ROOT);
		if (n.equals("Ogre bow") || n.equals("Comp ogre bow") || weapon.getCategory().equals("Salamander")
			|| n.equals("Hunters' crossbow") || n.equals("Hunters' sunlight crossbow") || n.equals("Training bow"))
		{
			return AmmoKind.UNSUPPORTED;
		}
		if (n.equals("Karil's crossbow"))
		{
			return AmmoKind.BOLT_RACK;
		}
		if (n.equals("Eclipse atlatl"))
		{
			return AmmoKind.ATLATL_DART;
		}
		if (lower.contains("ballista"))
		{
			return AmmoKind.JAVELIN;
		}
		if (weapon.getCategory().equals("Crossbow"))
		{
			return crossbowTier(n) > 0 ? AmmoKind.BOLT : AmmoKind.NONE;
		}
		if (weapon.getCategory().equals("Bow"))
		{
			return bowTier(n) > 0 ? AmmoKind.ARROW : AmmoKind.NONE;
		}
		return AmmoKind.NONE;
	}

	/**
	 * Whether an ammo item's ranged bonuses apply with this weapon (the calculator's INCLUDED state).
	 */
	public static boolean ammoUsable(GearItem weapon, GearItem ammo)
	{
		if (ammo == null)
		{
			return false;
		}
		String a = ammo.getName();
		String lower = a.toLowerCase(Locale.ROOT);
		switch (ammoKind(weapon))
		{
			case ARROW:
			{
				int tier = arrowTier(lower);
				return tier > 0 && tier <= bowTier(weapon.getName());
			}
			case BOLT:
			{
				int tier = boltTier(lower);
				return tier > 0 && tier <= crossbowTier(weapon.getName());
			}
			case JAVELIN:
				return lower.endsWith("javelin") && !lower.startsWith("morrigan");
			case BOLT_RACK:
				return a.equals("Bolt rack");
			case ATLATL_DART:
				return a.equals("Atlatl dart");
			default:
				return false;
		}
	}


	private static int bowTier(String name)
	{
		String lower = name.toLowerCase(Locale.ROOT);
		if (name.equals("Shortbow") || name.equals("Longbow") || name.equals("Cursed goblin bow") || name.equals("Rain bow"))
		{
			return 1;
		}
		if (lower.startsWith("oak ") || name.equals("Signed oak bow"))
		{
			return 5;
		}
		if (lower.startsWith("willow "))
		{
			return 20;
		}
		if (lower.startsWith("maple "))
		{
			return 30;
		}
		if (lower.startsWith("yew "))
		{
			return 40;
		}
		if (lower.startsWith("magic ") || name.equals("Bone shortbow") || name.equals("Seercull"))
		{
			return 50;
		}
		if (lower.startsWith("dark bow") || lower.equals("3rd age bow") || lower.contains("venator bow")
			|| name.equals("Twisted bow") || name.equals("Scorching bow") || name.equals("Nature's recurve"))
		{
			return 60;
		}
		return 0;
	}

	private static int arrowTier(String lower)
	{
		if (!lower.contains("arrow") || lower.contains("arrowtips") || lower.contains("ogre") || lower.contains("brutal")
			|| lower.contains("training"))
		{
			return 0;
		}
		if (lower.startsWith("bronze") || lower.startsWith("iron"))
		{
			return 1;
		}
		if (lower.startsWith("steel"))
		{
			return 5;
		}
		if (lower.startsWith("mithril"))
		{
			return 20;
		}
		if (lower.startsWith("adamant"))
		{
			return 30;
		}
		if (lower.startsWith("rune") || lower.startsWith("ice arrow"))
		{
			return 40;
		}
		if (lower.startsWith("amethyst") || lower.startsWith("broad") || lower.startsWith("seeking broad"))
		{
			return 50;
		}
		if (lower.startsWith("dragon"))
		{
			return 60;
		}
		return 0;
	}

	private static int crossbowTier(String name)
	{
		switch (name)
		{
			case "Crossbow":
			case "Phoenix crossbow":
			case "Bronze crossbow":
				return 1;
			case "Blurite crossbow":
			case "Dorgeshuun crossbow":
				return 16;
			case "Iron crossbow":
				return 26;
			case "Steel crossbow":
				return 31;
			case "Mithril crossbow":
				return 36;
			case "Adamant crossbow":
				return 46;
			case "Rune crossbow":
				return 61;
			case "Dragon crossbow":
			case "Dragon hunter crossbow":
			case "Armadyl crossbow":
			case "Zaryte crossbow":
			case "King's barrage":
				return 64;
			default:
				return 0;
		}
	}

	private static int boltTier(String lower)
	{
		if (!lower.contains("bolts") || lower.contains("bolt rack") || lower.contains("kebbit") || lower.contains("antler")
			|| lower.contains("unf") || lower.contains("bone bolts") || lower.contains("barbed"))
		{
			return 0;
		}
		if (lower.contains("dragon bolts") || lower.contains(" dragon bolts"))
		{
			return 64;
		}
		if (lower.startsWith("bronze") || lower.startsWith("opal"))
		{
			return 1;
		}
		if (lower.startsWith("blurite") || lower.startsWith("jade"))
		{
			return 16;
		}
		if (lower.startsWith("iron") || lower.startsWith("pearl") || lower.startsWith("silver"))
		{
			return 26;
		}
		if (lower.startsWith("steel") || lower.startsWith("topaz"))
		{
			return 31;
		}
		if (lower.startsWith("mithril") || lower.startsWith("sapphire") || lower.startsWith("emerald"))
		{
			return 36;
		}
		if (lower.startsWith("adamant") || lower.startsWith("ruby") || lower.startsWith("diamond"))
		{
			return 46;
		}
		if (lower.startsWith("runite") || lower.startsWith("broad") || lower.startsWith("amethyst broad")
			|| lower.startsWith("dragonstone") || lower.startsWith("onyx"))
		{
			return 61;
		}
		return 0;
	}

	/**
	 * Attack types this weapon (null for unarmed) can use for the optimiser.
	 */
	public static Set<AttackType> attackTypes(GearItem weapon)
	{
		Set<AttackType> out = EnumSet.noneOf(AttackType.class);
		String category = weapon == null ? "Unarmed" : weapon.getCategory();
		for (AttackType t : AttackType.values())
		{
			if (!stances(category, t).isEmpty())
			{
				out.add(t);
			}
		}
		if (weapon != null)
		{
			if (out.contains(AttackType.RANGED) && ammoKind(weapon) == AmmoKind.UNSUPPORTED)
			{
				out.remove(AttackType.RANGED);
			}
			if (category.startsWith("Powered") && !isSupportedPoweredStaff(weapon.getName()))
			{
				out.remove(AttackType.MAGIC);
			}
		}
		return out;
	}

	/**
	 * Two ranged weapons with the same key accept exactly the same ammo.
	 */
	public static String ammoKey(GearItem weapon)
	{
		AmmoKind kind = ammoKind(weapon);
		switch (kind)
		{
			case ARROW:
				return kind + ":" + bowTier(weapon.getName());
			case BOLT:
				return kind + ":" + crossbowTier(weapon.getName());
			default:
				return kind.name();
		}
	}
}

package com.bossingbis.data;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The combat styles the optimiser searches. Each one is optimised separately. BURST is magic with
 * an Ancient burst or barrage on a stack of monsters; the calculator itself only ever sees MAGIC.
 */
@Getter
@RequiredArgsConstructor
public enum AttackType
{
	STAB("Stab"),
	SLASH("Slash"),
	CRUSH("Crush"),
	RANGED("Ranged"),
	MAGIC("Magic"),
	BURST("Burst");

	private final String displayName;

	public boolean isMelee()
	{
		return this == STAB || this == SLASH || this == CRUSH;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.bossingbis.data;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum EquipmentSlot
{
	HEAD("head", "Head"),
	CAPE("cape", "Cape"),
	NECK("neck", "Neck"),
	AMMO("ammo", "Ammo"),
	WEAPON("weapon", "Weapon"),
	BODY("body", "Body"),
	SHIELD("shield", "Shield"),
	LEGS("legs", "Legs"),
	HANDS("hands", "Hands"),
	FEET("feet", "Feet"),
	RING("ring", "Ring");

	private final String key;
	private final String displayName;

	public static EquipmentSlot fromKey(String key)
	{
		for (EquipmentSlot s : values())
		{
			if (s.key.equals(key))
			{
				return s;
			}
		}
		return null;
	}
}

package com.bossingbis.data;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Equipment and monster stats bundled with the plugin. The data is the same data the
 * OSRS Wiki DPS calculator uses (https://github.com/weirdgloop/osrs-dps-calc), reduced
 * to the fields the calculation needs.
 */
public class GameData
{
	private final Map<Integer, GearItem> itemsById = new HashMap<>();
	private final Map<Integer, Integer> aliasToBase = new HashMap<>();
	private final Map<Integer, Monster> monstersById = new HashMap<>();
	private final List<Monster> monsters = new ArrayList<>();

	public static GameData load(Gson gson) throws IOException
	{
		GameData data = new GameData();
		data.loadEquipment(gson);
		data.loadMonsters(gson);
		return data;
	}

	private static Reader open(String name) throws IOException
	{
		InputStream in = GameData.class.getResourceAsStream("/com/bossingbis/" + name);
		if (in == null)
		{
			throw new IOException("Missing resource " + name);
		}
		return new InputStreamReader(in, StandardCharsets.UTF_8);
	}

	private void loadEquipment(Gson gson) throws IOException
	{
		Map<Integer, Integer> weights = new HashMap<>();
		try (Reader reader = open("weights.json"))
		{
			for (Map.Entry<String, JsonElement> w : gson.fromJson(reader, JsonObject.class).entrySet())
			{
				weights.put(Integer.parseInt(w.getKey()), w.getValue().getAsInt());
			}
		}
		try (Reader reader = open("equipment.json"))
		{
			JsonObject root = gson.fromJson(reader, JsonObject.class);
			for (JsonElement e : root.getAsJsonArray("items"))
			{
				JsonArray a = e.getAsJsonArray();
				EquipmentSlot slot = EquipmentSlot.fromKey(a.get(3).getAsString());
				if (slot == null)
				{
					continue;
				}
				GearItem item = new GearItem(
					a.get(0).getAsInt(), a.get(1).getAsString(), a.get(2).getAsString(), slot,
					a.get(4).getAsInt(), a.get(5).getAsString(), a.get(6).getAsInt() == 1,
					a.get(7).getAsInt(), a.get(8).getAsInt(), a.get(9).getAsInt(), a.get(10).getAsInt(), a.get(11).getAsInt(),
					a.get(12).getAsInt(), a.get(13).getAsInt(), a.get(14).getAsInt(),
					weights.getOrDefault(a.get(0).getAsInt(), 0));
				itemsById.put(item.getId(), item);
			}
			for (Map.Entry<String, JsonElement> alias : root.getAsJsonObject("aliases").entrySet())
			{
				aliasToBase.put(Integer.parseInt(alias.getKey()), alias.getValue().getAsInt());
			}
		}
	}

	private void loadMonsters(Gson gson) throws IOException
	{
		try (Reader reader = open("monsters.json"))
		{
			JsonArray root = gson.fromJson(reader, JsonArray.class);
			for (JsonElement e : root)
			{
				JsonArray a = e.getAsJsonArray();
				Set<String> attrs = new HashSet<>();
				for (JsonElement attr : a.get(16).getAsJsonArray())
				{
					attrs.add(attr.getAsString());
				}
				Monster m = new Monster(
					a.get(0).getAsInt(), a.get(1).getAsString(), a.get(2).getAsString(), a.get(3).getAsInt(),
					a.get(4).getAsInt(), a.get(5).getAsInt(), a.get(6).getAsInt(), a.get(7).getAsInt(),
					a.get(8).getAsInt(), a.get(9).getAsInt(), a.get(10).getAsInt(), a.get(11).getAsInt(),
					a.get(12).getAsInt(), a.get(13).getAsInt(), a.get(14).getAsInt(), a.get(15).getAsInt(),
					Collections.unmodifiableSet(attrs), a.get(17).getAsInt() == 1,
					a.get(18).getAsString(), a.get(19).getAsInt());
				monsters.add(m);
				monstersById.putIfAbsent(m.getId(), m);
			}
		}
	}

	/**
	 * Returns the stats to use for an owned item id, following cosmetic/locked/degraded variants
	 * back to their base item the same way the wiki calculator does.
	 */
	public GearItem getItem(int itemId)
	{
		Integer base = aliasToBase.get(itemId);
		if (base != null && itemsById.containsKey(base))
		{
			return itemsById.get(base);
		}
		return itemsById.get(itemId);
	}

	/**
	 * An item with this exact name, preferring usable (charged, active) variants and then the
	 * version-less entry.
	 */
	public GearItem findItem(String name)
	{
		GearItem found = null;
		for (GearItem item : itemsById.values())
		{
			if (item.getName().equals(name) && (found == null || findRank(item) < findRank(found)))
			{
				found = item;
			}
		}
		return found;
	}

	private static int findRank(GearItem item)
	{
		return (item.isUsable() ? 0 : 2) + (item.getVersion().isEmpty() ? 0 : 1);
	}

	/**
	 * For an unusable variant (uncharged, empty, inactive, broken), the usable version of the same
	 * item, or null if there is none.
	 */
	public GearItem findUsableVariant(GearItem item)
	{
		if (item.isUsable())
		{
			return item;
		}
		GearItem found = null;
		for (GearItem other : itemsById.values())
		{
			if (other.getName().equals(item.getName()) && other.getSlot() == item.getSlot() && other.isUsable()
				&& (found == null || preferredVariant(other) < preferredVariant(found)))
			{
				found = other;
			}
		}
		return found;
	}

	private static int preferredVariant(GearItem item)
	{
		switch (item.getVersion())
		{
			case "Charged":
			case "Active":
			case "100":
				return 0;
			case "":
				return 1;
			default:
				return 2;
		}
	}

	public Monster getMonster(int npcId)
	{
		return monstersById.get(npcId);
	}

	public List<Monster> getMonsters()
	{
		return Collections.unmodifiableList(monsters);
	}
}

package com.bossingbis.data;

import lombok.Value;

/**
 * Combat-relevant stats of one equippable item, as used by the OSRS Wiki DPS calculator.
 * Magic damage is stored in tenths of a percent (occult necklace = 50).
 */
@Value
public class GearItem
{
	int id;
	String name;
	String version;
	EquipmentSlot slot;
	int speed;
	String category;
	boolean twoHanded;
	int stab;
	int slash;
	int crush;
	int magic;
	int ranged;
	int strength;
	int rangedStrength;
	int magicDamage;
	/** Weight in grams (negative for weight-reducing items such as graceful). */
	int weight;

	/**
	 * Whether this variant can actually be used in combat. Uncharged, empty, inactive and broken
	 * variants are listed in the data but cannot attack (weapons) or be worn (broken armour).
	 */
	public boolean isUsable()
	{
		switch (version)
		{
			case "Broken":
			case "Inactive":
			case "0":
				return false;
			case "Uncharged":
			case "Empty":
				return slot != EquipmentSlot.WEAPON;
			default:
				return true;
		}
	}

	public int offensive(AttackType type)
	{
		switch (type)
		{
			case STAB:
				return stab;
			case SLASH:
				return slash;
			case CRUSH:
				return crush;
			case MAGIC:
				return magic;
			case RANGED:
				return ranged;
			default:
				return 0;
		}
	}

	@Override
	public String toString()
	{
		return name;
	}
}

