/**
 * Offline checks of the whole-fight plan: the main set against the first monster, and switches for
 * the rest. No game client involved.
 */
public class FightPlanTest
{
	private static GameData data;
	private static MonsterResolver resolver;

	@BeforeClass
	public static void load() throws Exception
	{
		data = GameData.load(new Gson());
		resolver = new MonsterResolver(data);
	}

	private static final PlayerSetup SETUP = PlayerSetup.builder().attack(99).strength(99).ranged(99).magic(99)
		.hitpoints(99).blowpipeDartStrength(35).build();

	/** A mid-level bank with a set for each style. */
	private static final String[] BANK = {"Abyssal whip", "Dragon defender", "Fighter torso", "Bandos tassets",
		"Helm of Neitiznot", "Barrows gloves", "Dragon boots", "Amulet of fury", "Fire cape", "Berserker ring (i)",
		"Rune crossbow", "Adamant bolts", "Black d'hide body", "Black d'hide chaps", "Ava's accumulator",
		"Trident of the Swamp", "Occult necklace", "Mystic robe top", "Mystic robe bottom", "Dragon warhammer"};

	/**
	 * A whole-fight plan for the Dagannoth Kings with this switch tolerance, printed for checking.
	 */
	private static List<OptimizationOutcome.Phase> planKings(int tolerance, List<PrepPlan.Switch> switches,
		StyleResult[] mainOut)
	{
		List<Optimizer.Candidate> bank = new ArrayList<>();
		Map<Integer, String> names = new HashMap<>();
		for (String n : BANK)
		{
			GearItem item = data.findItem(n);
			assertNotNull(n, item);
			bank.add(new Optimizer.Candidate(item, item.getId()));
			names.put(item.getId(), item.getName());
		}
		List<Monster> kings = resolver.forBoss(List.of("Dagannoth Rex", "Dagannoth Prime", "Dagannoth Supreme"));
		Monster rex = kings.get(0);
		AtomicBoolean cancel = new AtomicBoolean();
		Optimizer optimizer = new Optimizer(SETUP, rex, cancel);
		StyleResult main = null;
		for (AttackType t : AttackType.values())
		{
			if (t == AttackType.BURST)
			{
				continue;
			}
			StyleResult r = optimizer.optimise(bank, t);
			if (r.isValid() && (main == null || r.getResult().getDps() > main.getResult().getDps()))
			{
				main = r;
			}
		}
		assertNotNull(main);
		mainOut[0] = main;

		List<OptimizationOutcome.Phase> phases = new ArrayList<>();
		Set<String> weapons = new HashSet<>();
		BossingBisPlugin.planPhases(kings, rex, main, SETUP, cancel, bank, Collections.emptyMap(),
			Collections.emptyList(), 0, tolerance, names, phases, switches, weapons);
		System.out.println("tolerance " + tolerance + "%:");
		for (OptimizationOutcome.Phase p : phases)
		{
			System.out.printf("  %s: %s %.2f DPS (gave up %.2f, saved %d), switches %s%n", p.getMonster().getName(),
				p.getType(), p.getDps(), p.getDpsGivenUp(), p.getSwitchesSaved(),
				p.getSwitches().stream().map(c -> c.getItem().getName()).collect(java.util.stream.Collectors.toList()));
		}
		return phases;
	}

	@Test
	public void dagannothKingsGetSwitchesForEachKing()
	{
		List<PrepPlan.Switch> switches = new ArrayList<>();
		StyleResult[] main = new StyleResult[1];
		List<OptimizationOutcome.Phase> phases = planKings(0, switches, main);
		assertEquals(3, phases.size());
		assertEquals("Dagannoth Rex", phases.get(0).getMonster().getName());
		assertTrue(phases.get(0).getSwitches().isEmpty());
		// Prime and Supreme are weak to other styles than Rex, so there are switches
		assertTrue(switches.size() >= 2);
		for (OptimizationOutcome.Phase p : phases.subList(1, 3))
		{
			// with no tolerance, every phase uses its best set
			assertEquals(0, p.getSwitchesSaved());
			assertEquals(0, p.getDpsGivenUp(), 1e-9);
			for (Optimizer.Candidate c : p.getSwitches())
			{
				Optimizer.Candidate mainItem = main[0].getGear()[c.getItem().getSlot().ordinal()];
				assertTrue(mainItem == null || mainItem.getItem().getId() != c.getItem().getId());
			}
		}
		// every switch is listed once
		assertEquals(switches.size(), new HashSet<>(switches).size());
		assertTrue(switches.stream().allMatch(s -> s.getNote().startsWith("switch for ")));
		assertTrue(main[0].getGear()[EquipmentSlot.WEAPON.ordinal()] != null);
	}

	@Test
	public void toleranceCarriesFewerSwitchesForLittleDps()
	{
		List<PrepPlan.Switch> all = new ArrayList<>();
		List<OptimizationOutcome.Phase> best = planKings(0, all, new StyleResult[1]);
		// the default, printed for comparison
		List<PrepPlan.Switch> byDefault = new ArrayList<>();
		planKings(10, byDefault, new StyleResult[1]);
		assertTrue(byDefault.size() <= all.size());
		List<PrepPlan.Switch> fewer = new ArrayList<>();
		List<OptimizationOutcome.Phase> trimmed = planKings(25, fewer, new StyleResult[1]);
		assertTrue("expected fewer switches: " + fewer.size() + " vs " + all.size(), fewer.size() < all.size());
		for (int i = 1; i < trimmed.size(); i++)
		{
			OptimizationOutcome.Phase full = best.get(i);
			OptimizationOutcome.Phase p = trimmed.get(i);
			assertTrue(p.getSwitches().size() <= full.getSwitches().size());
			// never more than 25% below the phase's best set
			assertTrue(p.getDps() * 125 >= full.getDps() * 100 - 1e-6);
			assertEquals(full.getDps() - p.getDps(), p.getDpsGivenUp(), 1e-9);
			assertEquals(full.getSwitches().size() - p.getSwitches().size(), p.getSwitchesSaved());
		}
	}

	@Test
	public void slayerHelmetCountsOnTaskOnlyBosses()
	{
		// task-only bosses are planned on task, where a Slayer helmet (i) beats a Neitiznot faceguard
		List<Optimizer.Candidate> bank = new ArrayList<>();
		for (String n : new String[]{"Abyssal whip", "Slayer helmet (i)", "Neitiznot faceguard", "Fighter torso",
			"Bandos tassets", "Dragon defender"})
		{
			GearItem item = data.findItem(n);
			assertNotNull(n, item);
			bank.add(new Optimizer.Candidate(item, item.getId()));
		}
		Monster cerberus = resolver.forBoss(List.of("Cerberus")).get(0);
		StyleResult onTask = new Optimizer(SETUP.toBuilder().onSlayerTask(true).build(), cerberus, new AtomicBoolean())
			.optimise(bank, AttackType.SLASH);
		StyleResult offTask = new Optimizer(SETUP, cerberus, new AtomicBoolean()).optimise(bank, AttackType.SLASH);
		assertEquals("Slayer helmet (i)", onTask.getGear()[EquipmentSlot.HEAD.ordinal()].getItem().getName());
		assertEquals("Neitiznot faceguard", offTask.getGear()[EquipmentSlot.HEAD.ordinal()].getItem().getName());
		assertTrue(onTask.getResult().getDps() > offTask.getResult().getDps());
	}

	@Test
	public void vorkathKeepsADragonfireShieldOverATwistedBuckler() throws Exception
	{
		PrepPlanner planner = new PrepPlanner(PrepData.load(new Gson()));
		List<Optimizer.Candidate> bank = new ArrayList<>();
		for (String n : new String[]{"Dragon hunter crossbow", "Adamant bolts", "Twisted buckler", "Anti-dragon shield",
			"Black d'hide body", "Black d'hide chaps", "Ava's accumulator", "Amulet of fury"})
		{
			GearItem item = data.findItem(n);
			assertNotNull(n, item);
			bank.add(new Optimizer.Candidate(item, item.getId()));
		}
		Monster vorkath = resolver.forBoss(List.of("Vorkath (Post-quest)")).get(0);
		Optimizer optimizer = new Optimizer(SETUP, vorkath, new AtomicBoolean());
		StyleResult best = optimizer.optimise(bank, AttackType.RANGED);
		assertEquals("Twisted buckler", best.getGear()[EquipmentSlot.SHIELD.ordinal()].getItem().getName());

		Map<AttackType, List<String>> notes = new java.util.EnumMap<>(AttackType.class);
		Map<AttackType, Double> cost = new java.util.EnumMap<>(AttackType.class);
		StyleResult kept = BossingBisPlugin.applyPreferences(optimizer, bank, AttackType.RANGED, best,
			Collections.emptyMap(), planner.preferences("vorkath"), 0, notes, cost);
		assertEquals("Anti-dragon shield", kept.getGear()[EquipmentSlot.SHIELD.ordinal()].getItem().getName());
		assertTrue(notes.get(AttackType.RANGED).get(0).startsWith("Anti-dragon shield kept on"));
		assertEquals(best.getResult().getDps() - kept.getResult().getDps(), cost.get(AttackType.RANGED), 1e-9);
		System.out.println(notes.get(AttackType.RANGED));
	}
}

package com.bossingbis.calc;

import com.bossingbis.data.AttackType;
import com.bossingbis.data.EquipmentSlot;
import com.bossingbis.data.GameData;
import com.bossingbis.data.GearItem;
import com.bossingbis.data.Monster;
import com.bossingbis.data.MonsterResolver;
import com.google.gson.Gson;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Offline checks of the DPS maths against known OSRS reference values. No game client involved.
 */
public class DpsCalculatorTest
{
	private static GameData data;
	private static Monster abyssalDemon;

	@BeforeClass
	public static void load() throws Exception
	{
		data = GameData.load(new Gson());
		abyssalDemon = new MonsterResolver(data).fromName("Abyssal demons");
	}

	static PlayerSetup maxed(boolean onTask)
	{
		return PlayerSetup.builder().attack(99).strength(99).ranged(99).magic(99).hitpoints(99)
			.onSlayerTask(onTask).blowpipeDartStrength(35).build();
	}

	static GearItem item(String name)
	{
		GearItem item = data.findItem(name);
		assertNotNull("missing item " + name, item);
		return item;
	}

	private static GearItem[] gear(String... names)
	{
		GearItem[] gear = new GearItem[EquipmentSlot.values().length];
		for (String n : names)
		{
			GearItem item = item(n);
			gear[item.getSlot().ordinal()] = item;
		}
		return gear;
	}

	@Test
	public void accuracyFormula()
	{
		assertEquals(1 - 10002.0 / (2 * 20001), DpsCalculator.normalAccuracy(20000, 10000), 1e-12);
		assertEquals(10000.0 / (2 * 20001), DpsCalculator.normalAccuracy(10000, 20000), 1e-12);
	}

	@Test
	public void twistedBowScalingCapsAt250Magic()
	{
		// at the 250 magic cap outside raids: 140% accuracy, 215% damage
		assertEquals(140, DpsCalculator.tbowScaling(100, 250, true));
		assertEquals(215, DpsCalculator.tbowScaling(100, 250, false));
	}

	@Test
	public void whipMaxHitAt99Strength()
	{
		// 99 strength, abyssal whip only, controlled (lash): ((99+8+1) * (82+64) + 320) / 640 = 25
		CalcResult r = new DpsCalculator(maxed(false), abyssalDemon).best(gear("Abyssal whip"), AttackType.SLASH);
		assertTrue(r.getDps() > 0);
		int max = r.getStance() == Stance.CONTROLLED ? 25 : (99 + 8) * (82 + 64) / 640;
		assertEquals(max, r.getMaxHit());
	}

	@Test
	public void poweredStaffMaxHits()
	{
		assertEquals(31, WeaponRules.poweredBaseMaxHit("Trident of the Swamp", 99));
		assertEquals(28, WeaponRules.poweredBaseMaxHit("Trident of the Seas", 99));
		assertEquals(34, WeaponRules.poweredBaseMaxHit("Tumeken's shadow", 99));
		assertEquals(33, WeaponRules.poweredBaseMaxHit("Sanguinesti staff", 99));
	}

	@Test
	public void slayerHelmBoostsMeleeOnTaskOnly()
	{
		GearItem[] withHelm = gear("Abyssal whip", "Slayer helmet (i)");
		double onTask = new DpsCalculator(maxed(true), abyssalDemon).best(withHelm, AttackType.SLASH).getDps();
		double offTask = new DpsCalculator(maxed(false), abyssalDemon).best(withHelm, AttackType.SLASH).getDps();
		assertTrue(onTask > offTask * 1.15);
	}

	@Test
	public void rangedNeedsCompatibleAmmo()
	{
		DpsCalculator calc = new DpsCalculator(maxed(false), abyssalDemon);
		assertEquals(0, calc.best(gear("Magic shortbow"), AttackType.RANGED).getDps(), 0);
		assertEquals(0, calc.best(gear("Magic shortbow", "Dragon arrow"), AttackType.RANGED).getDps(), 0);
		assertTrue(calc.best(gear("Magic shortbow", "Amethyst arrow"), AttackType.RANGED).getDps() > 0);
		// blowpipe needs nothing in the ammo slot
		assertTrue(calc.best(gear("Toxic blowpipe"), AttackType.RANGED).getDps() > 0);
	}

	@Test
	public void flyingMonstersAreImmuneToNonPolearmMelee()
	{
		Monster aviansie = new MonsterResolver(data).fromName("Aviansies");
		assertNotNull(aviansie);
		assertTrue(aviansie.has(Monster.FLYING));
		DpsCalculator calc = new DpsCalculator(maxed(false), aviansie);
		assertEquals(0, calc.best(gear("Abyssal whip"), AttackType.SLASH).getDps(), 0);
	}

	@Test
	public void standardSpellsAutocastFromStaff()
	{
		CalcResult r = new DpsCalculator(maxed(false), abyssalDemon).best(gear("Staff of fire"), AttackType.MAGIC);
		assertNotNull(r.getSpell());
		// the best spell depends on the demon's elemental weakness, but at 99 magic it is always a surge
		assertTrue(r.getSpell().getName().endsWith("Surge"));
		assertTrue(r.getMaxHit() >= 21);
		assertEquals(5, r.getAttackSpeedTicks());
	}

	@Test
	public void burstHitsEveryTargetAndNeedsTheLevel()
	{
		GearItem[] kodai = gear("Kodai wand");
		Spell barrage = Spell.ANCIENT.get(Spell.ANCIENT.size() - 1);
		assertEquals("Ice Barrage", barrage.getName());
		CalcResult one = new DpsCalculator(maxed(false), abyssalDemon).single(kodai, AttackType.MAGIC, Stance.AUTOCAST, barrage);
		PlayerSetup burst = maxed(false).toBuilder().ancientSpellbook(true).burstTargets(3).build();
		CalcResult three = new DpsCalculator(burst, abyssalDemon).best(kodai, AttackType.MAGIC);
		assertEquals("Ice Barrage", three.getSpell().getName());
		assertEquals(one.getDps() * 3, three.getDps(), 1e-9);
		assertEquals(one.getMaxHit(), three.getMaxHit());

		// Ice Burst at 70, nothing below Smoke Burst's 62
		PlayerSetup lower = burst.toBuilder().magic(75).build();
		assertEquals("Ice Burst", new DpsCalculator(lower, abyssalDemon).best(kodai, AttackType.MAGIC).getSpell().getName());
		PlayerSetup low = burst.toBuilder().magic(61).build();
		assertEquals(0, new DpsCalculator(low, abyssalDemon).best(kodai, AttackType.MAGIC).getDps(), 0);
	}
}

package com.bossingbis.calc;

import com.bossingbis.data.AttackType;
import com.bossingbis.data.GameData;
import com.bossingbis.data.GearItem;
import com.bossingbis.data.Monster;
import com.bossingbis.data.MonsterResolver;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertTrue;

/**
 * A worst-case bank: one of every equippable item in the game. Checks the search still finishes.
 */
public class OptimizerPerformanceTest
{
	@Test(timeout = 60_000)
	public void everyItemInTheGame() throws Exception
	{
		GameData data = GameData.load(new Gson());
		Monster target = new MonsterResolver(data).fromName("Abyssal demons");
		List<Optimizer.Candidate> bank = new ArrayList<>();
		for (int id = 0; id < 40_000; id++)
		{
			GearItem item = data.getItem(id);
			if (item != null && item.getId() == id)
			{
				bank.add(new Optimizer.Candidate(item, id));
			}
		}

		Optimizer optimizer = new Optimizer(DpsCalculatorTest.maxed(true), target);
		for (AttackType type : AttackType.values())
		{
			long start = System.nanoTime();
			// burst is magic with a burst setup, as the plugin runs it
			StyleResult r = type == AttackType.BURST
				? new Optimizer(DpsCalculatorTest.maxed(true).toBuilder().ancientSpellbook(true).burstTargets(3).build(), target)
					.optimise(bank, AttackType.MAGIC)
				: optimizer.optimise(bank, type);
			long ms = (System.nanoTime() - start) / 1_000_000;
			System.out.printf("%s: %.3f dps, %d -> %d items, %d combinations, %d ms, stopped early %s%n",
				type, r.getResult().getDps(), r.getItemsConsidered(), r.getItemsAfterPruning(),
				r.getCombinationsTried(), ms, r.isStoppedEarly());
			StringBuilder sb = new StringBuilder();
			for (Optimizer.Candidate c : r.getGear())
			{
				if (c != null)
				{
					sb.append(c.getItem().getName()).append(", ");
				}
			}
			System.out.println("  " + sb);
			assertTrue(r.isValid());
		}
	}

	@Test(timeout = 60_000)
	public void everyItemWithAMinimumWeight() throws Exception
	{
		GameData data = GameData.load(new Gson());
		Monster target = new MonsterResolver(data).fromName("Gryphons");
		List<Optimizer.Candidate> bank = new ArrayList<>();
		for (int id = 0; id < 40_000; id++)
		{
			GearItem item = data.getItem(id);
			if (item != null && item.getId() == id)
			{
				bank.add(new Optimizer.Candidate(item, id));
			}
		}
		Optimizer optimizer = new Optimizer(DpsCalculatorTest.maxed(true), target);
		for (AttackType type : new AttackType[]{AttackType.STAB, AttackType.RANGED, AttackType.MAGIC})
		{
			long start = System.nanoTime();
			StyleResult r = optimizer.optimise(bank, type, java.util.Collections.emptyMap(), 40000);
			System.out.printf("weighted %s: %.3f dps, %.1f kg, %d combinations, %d ms, stopped early %s%n", type,
				r.getResult().getDps(), Optimizer.weight(r.getGear()) / 1000.0, r.getCombinationsTried(),
				(System.nanoTime() - start) / 1_000_000, r.isStoppedEarly());
			assertTrue(r.isValid());
			assertTrue(Optimizer.weight(r.getGear()) >= 40000);
		}
	}
}

package com.bossingbis.calc;

import com.bossingbis.data.AttackType;
import com.bossingbis.data.EquipmentSlot;
import com.bossingbis.data.GameData;
import com.bossingbis.data.GearItem;
import com.bossingbis.data.Monster;
import com.bossingbis.data.MonsterResolver;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Offline checks of pruning, set handling and two-handed weapons using made-up banks.
 */
public class OptimizerTest
{
	private static GameData data;
	private static MonsterResolver resolver;

	@BeforeClass
	public static void load() throws Exception
	{
		data = GameData.load(new Gson());
		resolver = new MonsterResolver(data);
	}

	private static List<Optimizer.Candidate> bank(String... names)
	{
		List<Optimizer.Candidate> out = new ArrayList<>();
		for (String n : names)
		{
			GearItem item = data.findItem(n);
			assertNotNull("missing item " + n, item);
			out.add(new Optimizer.Candidate(item, item.getId()));
		}
		return out;
	}

	private static String nameIn(StyleResult r, EquipmentSlot slot)
	{
		Optimizer.Candidate c = r.getGear()[slot.ordinal()];
		return c == null ? null : c.getItem().getName();
	}

	private static Monster monster(String task)
	{
		Monster m = resolver.fromName(task);
		assertNotNull(m);
		return m;
	}

	@Test
	public void outclassedItemsAreRemoved()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Abyssal whip", "Bronze full helm", "Helm of Neitiznot", "Leather boots",
			"Dragon boots"), AttackType.SLASH);
		assertTrue(r.isValid());
		assertEquals("Helm of Neitiznot", nameIn(r, EquipmentSlot.HEAD));
		assertEquals("Dragon boots", nameIn(r, EquipmentSlot.FEET));
	}

	@Test
	public void twoHandedWeaponsNeverUseAShield()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Dragon 2h sword", "Dragon defender", "Rune scimitar"), AttackType.SLASH);
		assertTrue(r.isValid());
		Optimizer.Candidate weapon = r.getGear()[EquipmentSlot.WEAPON.ordinal()];
		if (weapon.getItem().isTwoHanded())
		{
			assertNull(nameIn(r, EquipmentSlot.SHIELD));
		}
	}

	@Test
	public void bestOfTwoHandedVersusWeaponAndShield()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		// the whip with a defender beats a dragon 2h sword against a 4-tick, high slash-defence target
		StyleResult r = o.optimise(bank("Dragon 2h sword", "Dragon defender", "Abyssal whip"), AttackType.SLASH);
		assertEquals("Abyssal whip", nameIn(r, EquipmentSlot.WEAPON));
		assertEquals("Dragon defender", nameIn(r, EquipmentSlot.SHIELD));
	}

	@Test
	public void completeSetIsTriedAsOneCandidate()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Abyssal whip", "Void melee helm", "Void knight top", "Void knight robe",
			"Void knight gloves", "Helm of Neitiznot"), AttackType.SLASH);
		assertTrue(r.getSetsConsidered().contains("Void Knight (melee)"));
		// void's 10% accuracy and strength beats loose pieces with these few other items
		assertEquals("Void melee helm", nameIn(r, EquipmentSlot.HEAD));
		assertEquals("Void knight top", nameIn(r, EquipmentSlot.BODY));
	}

	@Test
	public void slayerHelmChosenOnTask()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(true), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Abyssal whip", "Slayer helmet (i)", "Helm of Neitiznot"), AttackType.SLASH);
		assertEquals("Slayer helmet (i)", nameIn(r, EquipmentSlot.HEAD));
	}

	@Test
	public void rangedPicksCompatibleAmmo()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Magic shortbow", "Dragon arrow", "Rune arrow", "Bronze arrow"), AttackType.RANGED);
		assertTrue(r.isValid());
		assertEquals("Rune arrow", nameIn(r, EquipmentSlot.AMMO));
	}

	@Test
	public void leafyMonsterNeedsLeafBladedWeapon()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Kurask"));
		StyleResult r = o.optimise(bank("Abyssal whip", "Leaf-bladed sword"), AttackType.SLASH);
		assertEquals("Leaf-bladed sword", nameIn(r, EquipmentSlot.WEAPON));
	}

	@Test
	public void noUsableGearGivesNoResult()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Helm of Neitiznot"), AttackType.MAGIC);
		assertTrue(!r.isValid());
	}

	@Test
	public void taskNamesResolve()
	{
		assertEquals("Abyssal demon", monster("Abyssal demons").getName());
		assertEquals("Kalphite Soldier", monster("Kalphites").getName());
		assertEquals("Wolf", monster("Wolves").getName());
		assertEquals("Dwarf", monster("Dwarves").getName());
		assertEquals("Hellhound", monster("Hellhounds").getName());
		assertEquals("Steel dragon", monster("Metal dragons").getName());
	}

	@Test
	public void setPieceNamesExistInData()
	{
		for (GearSets set : GearSets.ALL)
		{
			for (List<String> names : set.getPieces().values())
			{
				boolean any = false;
				for (String n : names)
				{
					any |= data.findItem(n) != null;
				}
				assertTrue(set.getName() + " has an unknown piece " + names, any);
			}
		}
	}

	@Test
	public void unchargedVariantsAreNotUsable()
	{
		GearItem charged = null;
		GearItem empty = null;
		for (int id : new int[]{12926, 12924})
		{
			GearItem g = data.getItem(id);
			if ("Charged".equals(g.getVersion()))
			{
				charged = g;
			}
			else
			{
				empty = g;
			}
		}
		assertNotNull(charged);
		assertNotNull(empty);
		assertTrue(charged.isUsable());
		assertTrue(!empty.isUsable());
		// the charged version is offered as the "if charged" alternative
		assertEquals(charged.getId(), data.findUsableVariant(empty).getId());
	}

	@Test
	public void cancelFlagStopsTheSearch()
	{
		java.util.concurrent.atomic.AtomicBoolean cancel = new java.util.concurrent.atomic.AtomicBoolean(true);
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"), cancel);
		List<Optimizer.Candidate> everything = new ArrayList<>();
		for (int id = 0; id < 40_000; id++)
		{
			GearItem item = data.getItem(id);
			if (item != null && item.getId() == id && item.isUsable())
			{
				everything.add(new Optimizer.Candidate(item, id));
			}
		}
		try
		{
			o.optimise(everything, AttackType.RANGED);
			org.junit.Assert.fail("expected the search to stop");
		}
		catch (java.util.concurrent.CancellationException expected)
		{
			// stopped at the first check
		}
	}

	@Test
	public void requiredShieldIsAlwaysWornAndRulesOutTwoHanders()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(true), monster("Basilisks"));
		java.util.Map<EquipmentSlot, java.util.Set<String>> required = new java.util.EnumMap<>(EquipmentSlot.class);
		required.put(EquipmentSlot.SHIELD, new java.util.HashSet<>(java.util.Arrays.asList("Mirror shield", "V's shield")));
		StyleResult r = o.optimise(bank("Dragon 2h sword", "Abyssal whip", "Dragon defender", "Mirror shield"),
			AttackType.SLASH, required);
		assertEquals("Mirror shield", nameIn(r, EquipmentSlot.SHIELD));
		assertEquals("Abyssal whip", nameIn(r, EquipmentSlot.WEAPON));
	}

	@Test
	public void alternativesUseOtherWeapons()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		// different weapon types, so none is removed as outclassed by another
		StyleResult r = o.optimise(bank("Abyssal whip", "Dragon scimitar", "Dragon battleaxe"), AttackType.SLASH);
		assertEquals(2, r.getAlternatives().size());
		String best = nameIn(r, EquipmentSlot.WEAPON);
		for (StyleResult.Alternative alt : r.getAlternatives())
		{
			assertTrue(!best.equals(alt.getGear()[EquipmentSlot.WEAPON.ordinal()].getItem().getName()));
			assertTrue(alt.getResult().getDps() <= r.getResult().getDps());
		}
	}

	@Test
	public void bossEntriesFindVersionsOrEveryVersion()
	{
		List<Monster> vorkath = resolver.forBoss(List.of("Vorkath (Post-quest)"));
		assertEquals(1, vorkath.size());
		assertEquals("Post-quest", vorkath.get(0).getVersion());
		// a plain name brings every version
		assertEquals(3, resolver.forBoss(List.of("Zulrah")).size());
		List<Monster> dks = resolver.forBoss(List.of("Dagannoth Rex", "Dagannoth Prime", "Dagannoth Supreme"));
		assertEquals("Dagannoth Rex", dks.get(0).getName());
		assertEquals(3, dks.size());
	}

	@Test
	public void ammoOptionsListEveryUsableAmmoBestFirst()
	{
		List<Optimizer.Candidate> owned = bank("Twisted bow", "Dragon arrow", "Rune arrow", "Amethyst arrow",
			"Broad bolts", "Abyssal whip");
		Optimizer optimizer = new Optimizer(DpsCalculatorTest.maxed(true), monster("Abyssal demons"));
		StyleResult ranged = optimizer.optimise(owned, AttackType.RANGED);
		List<StyleResult.Alternative> options = optimizer.ammoOptions(ranged, owned);
		assertEquals(3, options.size());
		assertEquals("Dragon arrow", options.get(0).getGear()[EquipmentSlot.AMMO.ordinal()].getItem().getName());
		assertEquals(ranged.getResult().getDps(), options.get(0).getResult().getDps(), 1e-9);
		for (int i = 1; i < options.size(); i++)
		{
			assertTrue(options.get(i).getResult().getDps() <= options.get(i - 1).getResult().getDps());
			assertEquals("Twisted bow", options.get(i).getGear()[EquipmentSlot.WEAPON.ordinal()].getItem().getName());
		}
		// melee sets have no ammo to compare
		assertTrue(optimizer.ammoOptions(optimizer.optimise(owned, AttackType.SLASH), owned).isEmpty());
	}

	@Test
	public void gryphonSetsMeetTheWeight()
	{
		List<Optimizer.Candidate> owned = bank("Abyssal whip", "Dragon defender", "Fighter torso", "Bandos chestplate",
			"Bandos tassets", "Obsidian platelegs", "Neitiznot faceguard", "Helm of Neitiznot", "Barrows gloves",
			"Dragon boots", "Amulet of torture", "Fire cape", "Berserker ring (i)", "Granite maul");
		Optimizer optimizer = new Optimizer(DpsCalculatorTest.maxed(true), monster("Gryphons"));
		StyleResult free = optimizer.optimise(owned, AttackType.SLASH);
		StyleResult heavy = optimizer.optimise(owned, AttackType.SLASH, java.util.Collections.emptyMap(), 25000);
		assertTrue(heavy.isValid());
		assertTrue(Optimizer.weight(heavy.getGear()) >= 25000);
		assertTrue(heavy.getResult().getDps() <= free.getResult().getDps() + 1e-9);
		// impossible weight: nothing qualifies
		StyleResult impossible = optimizer.optimise(owned, AttackType.SLASH, java.util.Collections.emptyMap(), 500000);
		assertFalse(impossible.isValid());
	}

	@Test
	public void spellOptionsListEveryCastableSpellBestFirst()
	{
		List<Optimizer.Candidate> owned = bank("Trident of the Swamp", "Staff of the Dead", "Occult necklace");
		Optimizer optimizer = new Optimizer(DpsCalculatorTest.maxed(true), monster("Bloodveld"));
		StyleResult magic = optimizer.optimise(owned, AttackType.MAGIC);
		List<StyleResult.Alternative> spells = optimizer.spellOptions(magic);
		if (magic.getResult().getSpell() == null)
		{
			// a powered staff casts its own spell: nothing to pick
			assertTrue(spells.isEmpty());
			magic = optimizer.optimise(bank("Staff of the Dead", "Occult necklace"), AttackType.MAGIC);
			spells = optimizer.spellOptions(magic);
		}
		assertTrue(spells.size() > 5);
		assertEquals(magic.getResult().getDps(), spells.get(0).getResult().getDps(), 1e-9);
		assertTrue(spells.stream().anyMatch(a -> a.getResult().getSpell().getName().equals("Fire Strike")));
		for (int i = 1; i < spells.size(); i++)
		{
			assertTrue(spells.get(i).getResult().getDps() <= spells.get(i - 1).getResult().getDps());
		}
	}
}

package com.bossingbis.calc;

import com.bossingbis.data.AttackType;
import com.bossingbis.data.EquipmentSlot;
import com.bossingbis.data.GameData;
import com.bossingbis.data.GearItem;
import com.bossingbis.data.Monster;
import com.google.gson.Gson;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Loadouts whose results were checked by hand against the live OSRS Wiki DPS calculator
 * (https://tools.runescape.wiki/osrs-dps/, version 89c3e25) on 2026-10-19.
 *
 * <p>Calculator settings for every case: all skills 99, no prayers, no potions, the combat style
 * named in the case. "On Slayer task" only matters for the slayer helmet case.
 * Expected values are copied from the calculator's Results table, which rounds DPS to 3 decimal
 * places and accuracy to 2.</p>
 *
 * <p>Monster ids: 415 Abyssal demon (Standard), 7245 Greater demon (Level 100),
 * 8031 Rune dragon, 2516 Ankou (Level 86).</p>
 */
public class WikiReferenceTest
{
	private static final int ABYSSAL_DEMON = 415;
	private static final int GREATER_DEMON_100 = 7245;
	private static final int RUNE_DRAGON = 8031;
	private static final int ANKOU_86 = 2516;

	private static GameData data;

	@BeforeClass
	public static void load() throws Exception
	{
		data = GameData.load(new Gson());
	}

	private static PlayerSetup player(boolean onTask)
	{
		return PlayerSetup.builder().attack(99).strength(99).ranged(99).magic(99).hitpoints(99)
			.onSlayerTask(onTask).blowpipeDartStrength(35).build();
	}

	/**
	 * Calculates one stance directly, so the check does not depend on which stance the optimiser prefers.
	 */
	private static void check(int monsterId, AttackType type, Stance stance, boolean onTask,
		int maxHit, double accuracyPercent, double dps, String... items)
	{
		Monster monster = data.getMonster(monsterId);
		assertNotNull(monster);
		GearItem[] gear = new GearItem[EquipmentSlot.values().length];
		for (String name : items)
		{
			GearItem item = data.findItem(name);
			assertNotNull("missing item " + name, item);
			gear[item.getSlot().ordinal()] = item;
		}
		CalcResult r = new DpsCalculator(player(onTask), monster).single(gear, type, stance);
		String label = String.join(", ", items) + " vs " + monster.displayName() + " (" + stance + ")";
		assertEquals(label + ": max hit", maxHit, r.getMaxHit());
		assertEquals(label + ": accuracy", accuracyPercent, r.getAccuracy() * 100, 0.005);
		assertEquals(label + ": dps", dps, r.getDps(), 0.0005);
	}

	@Test
	public void whipOnly()
	{
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.ACCURATE, false, 24, 62.34, 3.127, "Abyssal whip");
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.CONTROLLED, false, 25, 61.64, 3.220, "Abyssal whip");
	}

	@Test
	public void midLevelMelee()
	{
		String[] gear = {"Abyssal whip", "Helm of Neitiznot", "Fire cape", "Amulet of fury", "Bandos chestplate",
			"Bandos tassets", "Dragon defender", "Barrows gloves", "Dragon boots", "Berserker ring (i)"};
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.CONTROLLED, false, 33, 70.98, 4.889, gear);
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.ACCURATE, false, 33, 71.51, 4.925, gear);
	}

	@Test
	public void slayerHelmetOnTask()
	{
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.ACCURATE, true, 28, 67.72, 3.960, "Abyssal whip", "Slayer helmet (i)");
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.CONTROLLED, true, 29, 67.12, 4.064, "Abyssal whip", "Slayer helmet (i)");
	}

	@Test
	public void arclightAgainstDemon()
	{
		check(GREATER_DEMON_100, AttackType.STAB, Stance.CONTROLLED, false, 20, 79.03, 3.309, "Arclight");
	}

	@Test
	public void blowpipeWithDragonDarts()
	{
		check(ABYSSAL_DEMON, AttackType.RANGED, Stance.RAPID, false, 23, 76.35, 7.343,
			"Toxic blowpipe", "Masori mask (f)", "Masori body (f)", "Masori chaps (f)", "Necklace of anguish",
			"Ava's assembler", "Zaryte vambraces", "Pegasian boots", "Venator ring");
	}

	@Test
	public void twistedBowAgainstLowMagic()
	{
		check(ABYSSAL_DEMON, AttackType.RANGED, Stance.RAPID, false, 12, 23.70, 0.480, "Twisted bow", "Dragon arrow");
	}

	@Test
	public void tridentOfTheSwamp()
	{
		check(ABYSSAL_DEMON, AttackType.MAGIC, Stance.ACCURATE, false, 37, 98.56, 7.608,
			"Trident of the Swamp", "Ancestral hat", "Ancestral robe top", "Ancestral robe bottom", "Occult necklace",
			"Tormented bracelet", "Eternal boots", "Magus ring");
	}

	@Test
	public void dragonHunterLanceAgainstDragon()
	{
		check(RUNE_DRAGON, AttackType.STAB, Stance.CONTROLLED, false, 27, 40.33, 2.274, "Dragon hunter lance");
	}

	@Test
	public void salveAgainstUndead()
	{
		check(ANKOU_86, AttackType.SLASH, Stance.ACCURATE, false, 28, 85.22, 4.983, "Abyssal whip", "Salve amulet(ei)");
		check(ANKOU_86, AttackType.SLASH, Stance.CONTROLLED, false, 30, 84.94, 5.320, "Abyssal whip", "Salve amulet(ei)");
	}

	/**
	 * Manual-cast Ice Barrage, as used for the Burst result. Checked on 2026-10-20 (version
	 * 89c3e25): "Magic, Manual Cast" with Ice Barrage selected, everything else as above.
	 */
	private static CalcResult barrage(String... items)
	{
		Monster monster = data.getMonster(ABYSSAL_DEMON);
		GearItem[] gear = new GearItem[EquipmentSlot.values().length];
		for (String name : items)
		{
			GearItem item = data.findItem(name);
			assertNotNull("missing item " + name, item);
			gear[item.getSlot().ordinal()] = item;
		}
		Spell barrage = Spell.ANCIENT.stream().filter(s -> s.getName().equals("Ice Barrage")).findFirst().get();
		return new DpsCalculator(player(false), monster).single(gear, AttackType.MAGIC, Stance.AUTOCAST, barrage);
	}

	private static void assertResult(CalcResult r, int maxHit, double accuracyPercent, double dps)
	{
		assertEquals("max hit", maxHit, r.getMaxHit());
		assertEquals("accuracy", accuracyPercent, r.getAccuracy() * 100, 0.005);
		assertEquals("dps", dps, r.getDps(), 0.0005);
	}

	@Test
	public void iceBarrageWithKodai()
	{
		assertResult(barrage("Kodai wand"), 34, 96.77, 5.493);
	}

	@Test
	public void iceBarrageWithVirtus()
	{
		assertResult(barrage("Kodai wand", "Virtus robe top"), 36, 97.66, 5.868);
	}

	@Test
	public void iceBarrageWithTumekensShadow()
	{
		// the shadow's bonuses are only tripled for its own spell, not a manual cast
		assertResult(barrage("Tumeken's shadow", "Virtus robe top"), 31, 97.78, 5.062);
	}
}

package com.bossingbis.prep;

import com.bossingbis.data.AttackType;
import com.bossingbis.data.EquipmentSlot;
import com.bossingbis.data.GameData;
import com.bossingbis.data.MonsterResolver;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Offline checks of the boss preparation data and suggestions. No game client involved.
 */
public class PrepPlannerTest
{
	private static PrepData data;
	private static PrepPlanner planner;
	private static GameData gameData;

	@BeforeClass
	public static void load() throws Exception
	{
		data = PrepData.load(new Gson());
		planner = new PrepPlanner(data);
		gameData = GameData.load(new Gson());
	}

	private static OwnedItems owned(Object... nameQty)
	{
		Map<String, Integer> q = new HashMap<>();
		Map<String, Set<Integer>> ids = new HashMap<>();
		for (int i = 0; i < nameQty.length; i += 2)
		{
			q.put((String) nameQty[i], (Integer) nameQty[i + 1]);
			ids.put((String) nameQty[i], new HashSet<>(Collections.singletonList(1000 + i)));
		}
		return OwnedItems.of(q, ids);
	}

	private static PrepPlanner.Request.RequestBuilder request(String boss, AttackType best, OwnedItems owned)
	{
		return PrepPlanner.Request.builder().boss(boss).bestType(best).owned(owned).prayerPotions(4)
			.combatPotions(1).fillFood(true);
	}

	private static List<String> names(PrepPlan plan)
	{
		List<String> out = new ArrayList<>();
		for (PrepPlan.InventoryLine l : plan.getInventory())
		{
			out.add(l.getName());
		}
		return out;
	}

	@Test
	public void namesMatchDosesAndCharges()
	{
		assertTrue(OwnedItems.matches("Prayer potion(3)", "Prayer potion"));
		assertTrue(OwnedItems.matches("Games necklace(8)", "Games necklace"));
		assertFalse(OwnedItems.matches("Magic potion(4)", "Divine magic potion"));
		assertFalse(OwnedItems.matches("Anti-venom+(4)", "Anti-venom"));
	}

	@Test
	public void everyBossHasMonstersLocationsAndTeleports()
	{
		MonsterResolver resolver = new MonsterResolver(gameData);
		assertTrue(data.bosses().size() >= 40);
		for (Map.Entry<String, PrepData.BossInfo> e : data.bosses().entrySet())
		{
			String key = e.getKey();
			PrepData.BossInfo info = e.getValue();
			assertEquals(key + " key must be lower case", key.toLowerCase(Locale.ROOT), key);
			assertNotNull(key + " has no name", info.name);
			assertFalse(key + " has no monsters", info.getMonsters().isEmpty());
			for (String m : info.getMonsters())
			{
				assertFalse(key + ": no monster stats for " + m, resolver.forBoss(List.of(m)).isEmpty());
			}
			assertNotNull(key + " has no locations", info.locations);
			for (String location : info.locations)
			{
				List<PrepData.Teleport> teleports = data.locations().get(location);
				assertNotNull(key + " lists unknown location " + location, teleports);
				assertFalse(location + " has no teleports", teleports.isEmpty());
				for (PrepData.Teleport t : teleports)
				{
					assertFalse(location + " has a teleport without text", t.text == null || t.text.trim().isEmpty());
				}
			}
		}
	}

	@Test
	public void slayerOnlyBossesAreMarked()
	{
		for (String boss : new String[]{"cerberus", "abyssal sire", "kraken", "thermonuclear smoke devil",
			"alchemical hydra", "grotesque guardians", "araxxor", "shellbane gryphon"})
		{
			assertNotNull(boss + " should need a Slayer task", data.boss(boss).getSlayerTask());
		}
		for (String boss : new String[]{"vorkath", "zulrah", "general graardor", "corporeal beast", "nex"})
		{
			assertEquals(boss + " needs no Slayer task", null, data.boss(boss).getSlayerTask());
		}
	}

	@Test
	public void requiredAndPreferredItemNamesExistInTheItemData()
	{
		for (Map.Entry<String, PrepData.BossInfo> e : data.bosses().entrySet())
		{
			PrepData.BossInfo info = e.getValue();
			if (info.required != null)
			{
				for (List<String> names : info.required.values())
				{
					for (String n : names)
					{
						if (!n.equals("Boots of brimstone"))
						{
							assertNotNull(e.getKey() + ": unknown item " + n, gameData.findItem(n));
						}
					}
				}
			}
			if (info.prefer != null)
			{
				for (PrepData.Preference p : info.prefer)
				{
					assertNotNull(e.getKey() + ": unknown slot " + p.slot, EquipmentSlot.fromKey(p.slot));
					assertFalse(e.getKey() + ": a preference needs a reason", p.reason == null || p.reason.isEmpty());
					for (String n : p.items)
					{
						assertNotNull(e.getKey() + ": unknown item " + n, gameData.findItem(n));
					}
				}
			}
		}
	}

	/**
	 * The data must stay a planner for before the trip. Gear reasons may mention mechanics and prayer
	 * effects, as the wiki does, but never tell you what to do in the fight: no prayer instructions,
	 * timing, positioning or what's coming next.
	 */
	@Test
	public void bossDataHasNoFightHelp() throws Exception
	{
		String text;
		try (java.io.InputStream in = PrepData.class.getResourceAsStream("/com/bossingbis/bosses.json"))
		{
			text = new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8).toLowerCase(Locale.ROOT);
		}
		// the format note at the top names what's forbidden; check everything after it
		text = text.substring(text.indexOf("\"bosses\""));
		for (String banned : new String[]{
			// positioning
			"safespot", "safe spot", "stand ", "standing", "tile", "dodge",
			// prayer instructions
			"protect from", "pray against", "switch prayer", "turn on", "activate", "piety", "rigour", "augury",
			// timing and what's coming
			"flinch", "next attack", "when it", "when he", "when she", "when the", "as soon as", "swap to"})
		{
			assertFalse("boss data mentions \"" + banned + "\"", text.contains(banned));
		}
	}

	@Test
	public void entryItemsTeleportAndFood()
	{
		OwnedItems bank = owned("Mith grapple", 1, "Prayer potion(4)", 10, "Ranging potion(4)", 2, "Shark", 100);
		PrepPlan plan = planner.plan(request("kree'arra", AttackType.RANGED, bank).build());
		assertEquals("Mith grapple", plan.getInventory().get(0).getName());
		assertTrue(names(plan).contains("Ranging potion(4)") || names(plan).contains("Ranging potion"));
		assertEquals(PrepPlanner.INVENTORY_SLOTS, plan.getSlotsUsed());
		assertTrue(plan.getTeleports().stream().allMatch(t -> t.getLocation().equals("God Wars Dungeon")));
	}

	@Test
	public void crossbowForTheGrappleUnlessOneIsWorn()
	{
		OwnedItems bank = owned("Mith grapple", 1, "Rune crossbow", 1, "Armadyl crossbow", 1, "Shark", 100);
		PrepPlan carried = planner.plan(request("kree'arra", AttackType.RANGED, bank).build());
		assertTrue(names(carried).contains("Rune crossbow"));
		// wearing any crossbow in the planned set: no extra one
		PrepPlan worn = planner.plan(request("kree'arra", AttackType.RANGED, bank)
			.wornNames(Set.of("Armadyl crossbow")).build());
		assertTrue(names(worn).stream().noneMatch(n -> n.endsWith("crossbow")));
		assertTrue(names(worn).contains("Mith grapple"));
	}

	@Test
	public void godWarsBossesGetTheFollowersTip()
	{
		for (String boss : new String[]{"general graardor", "commander zilyana", "k'ril tsutsaroth", "kree'arra", "nex"})
		{
			assertTrue(boss, data.boss(boss).tips.stream().anyMatch(t -> t.contains("followers")));
		}
		assertFalse(planner.preferences("vorkath").isEmpty());
		assertEquals(EquipmentSlot.RING, planner.preferences("zulrah").get(0).getSlot());
	}

	@Test
	public void batchTwoReviewData()
	{
		// a dragonfire-protecting shield for the KBD, a recoil ring for the Kalphite Queen, Aranea boots for Sarachnis
		assertEquals(EquipmentSlot.SHIELD, planner.preferences("king black dragon").get(0).getSlot());
		assertEquals(EquipmentSlot.RING, planner.preferences("kalphite queen").get(0).getSlot());
		assertEquals(EquipmentSlot.FEET, planner.preferences("sarachnis").get(0).getSlot());
		assertTrue(planner.poisons("dagannoth kings"));
		assertTrue(planner.poisons("kalphite queen"));
		// optional entry items only show when owned
		PrepPlan without = planner.plan(request("dagannoth kings", AttackType.RANGED, owned("Shark", 50)).build());
		assertFalse(names(without).contains("Rune thrownaxe"));
		PrepPlan with = planner.plan(request("dagannoth kings", AttackType.RANGED,
			owned("Rune thrownaxe", 1, "Pet rock", 1, "Shark", 50)).build());
		assertTrue(names(with).containsAll(List.of("Rune thrownaxe", "Pet rock")));
	}

	@Test
	public void mechanicReasonsFromTheWiki()
	{
		// Spectral spirit shield for its prayer-drain reduction
		assertEquals("Spectral spirit shield", planner.preferences("k'ril tsutsaroth").get(0).getItems().get(0));
		assertEquals("Spectral spirit shield", planner.preferences("nex").get(0).getItems().get(0));
		// Ghommal's hilt for the Barrows tunnels, best tier owned
		PrepPlan barrows = planner.plan(request("barrows brothers", AttackType.MAGIC,
			owned("Spade", 1, "Ghommal's hilt 2", 1, "Ghommal's hilt 4", 1, "Shark", 50)).build());
		assertTrue(names(barrows).contains("Ghommal's hilt 4"));
		assertFalse(names(barrows).contains("Ghommal's hilt 2"));
		// Corp: the stat-draining special attack weapons, alongside the usual spec weapon
		PrepPlan corp = planner.plan(request("corporeal beast", AttackType.STAB,
			owned("Arclight", 1, "Bandos godsword", 1, "Dragon warhammer", 1, "Shark", 50))
			.monsterHitpoints(2000).suggestSpecWeapon(true).build());
		assertTrue(names(corp).containsAll(List.of("Arclight", "Bandos godsword", "Dragon warhammer")));
		// more ways to Slepe
		assertTrue(planner.plan(request("the nightmare", AttackType.SLASH, owned("Ectophial", 1)).build())
			.getTeleports().stream().anyMatch(t -> t.getText().startsWith("Ectophial") && Boolean.TRUE.equals(t.getOwned())));
	}

	@Test
	public void wikiSwitchesAreOwnedOnlyAndCanBeTurnedOff()
	{
		OwnedItems bank = owned("Hallowfell", 1, "Blisterwood stake", 1, "Shark", 50);
		PrepPlan on = planner.plan(request("phosani's nightmare", AttackType.CRUSH, bank).build());
		assertTrue(names(on).containsAll(List.of("Hallowfell", "Blisterwood stake")));
		// Dinh's bulwark isn't owned, so it isn't suggested
		assertFalse(names(on).contains("Dinh's bulwark"));
		assertTrue(on.getInventory().stream().filter(l -> l.getName().equals("Hallowfell"))
