		PrepPlan staff = planner.plan(request("skotizo", AttackType.MAGIC, owned("Dark totem", 1, "Rune pouch", 1,
			"Law rune", 100)).spellbook("standard").magicLevel(99).finishedQuests(Set.of("CLIENT_OF_KOUREND"))
